async fn shell() -> Response {
    (
        StatusCode::OK,
        [("content-type", "text/html; charset=utf-8")],
        r#"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Frickmail</title>
</head>
<body>
  <main>
    <h1>Frickmail Rust migration server</h1>
    <p>The Rust backend is active. Mail UI/API migration is in progress.</p>
  </main>
</body>
</html>"#,
    )
        .into_response()
}

async fn root_get(
    State(state): State<AppState>,
    session: fm_session::Session,
    OriginalUri(uri): OriginalUri,
    request: AxumRequest,
) -> Response {
    let index_root = std::path::PathBuf::from(state.config().static_root.clone());
    if let Some(admin) = legacy_admin_app_data_route(&uri) {
        return native_admin_app_data(&state, admin, &session).await;
    }
    if let Some(raw_key) = legacy_attachment_export_download_route(&uri) {
        return native_legacy_attachment_export_download(&state, raw_key, &session).await;
    }
    if is_legacy_json_request(&uri) {
        return json_api_request(state, uri, request, session).await;
    }

    if let Some(response) = native_oidc_part_hook(&state, &uri, &session).await {
        return response;
    }

    match tokio::fs::read(index_root.join("index.html")).await {
        Ok(body) => (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            body,
        )
            .into_response(),
        Err(_) => shell().await,
    }
}

/// Handles the `StartLoginOIDC` and `LoginOIDC` part hooks natively.
///
/// These are GET requests to `/?StartLoginOIDC` (optionally with `&mode=link`)
/// and `/?LoginOIDC&code=…&state=…` (the OIDC provider's redirect).
/// Returns `None` when the request is not an OIDC part hook, allowing the
/// caller to fall through to index.html.
async fn native_oidc_part_hook(
    state: &AppState,
    uri: &Uri,
    session: &fm_session::Session,
) -> Option<Response> {
    let _query = uri.query()?;
    let params = query_map(uri);

    // Detect: ?StartLoginOIDC or ?StartLoginOIDC&mode=link
    if params.contains_key("StartLoginOIDC") {
        return Some(native_oidc_start_login(state, &params).await);
    }

    // Detect: ?LoginOIDC&code=…&state=…
    // Some providers strip the first query key, so also check for code+state
    // with a decryptable OIDC state when LoginOIDC is absent.
    if params.contains_key("LoginOIDC") {
        return Some(
            native_oidc_login(state, uri, &params, session, "LoginOIDC").await,
        );
    }

    // Fallback: if the query has code+state but no explicit LoginOIDC key,
    // try to decrypt the state to see if it's an OIDC callback.
    if params.contains_key("code") && params.contains_key("state") {
        let state_str = params.get("state").map(|s| s.as_str()).unwrap_or_default();
        if fm_oidc::is_oidc_state(state_str, state.config().app_salt.as_deref().unwrap_or("")) {
            return Some(
                native_oidc_login(state, uri, &params, session, "code").await,
            );
        }
    }

    None
}

/// Handles `?StartLoginOIDC` — initiates the OIDC authorization-code flow with PKCE.
///
/// Supports `mode=link` (require existing session) and the default `mode=login`.
/// The `mode` comes from the encrypted state, which `start_login` encodes, so it
/// is read from the query for link-mode validation.
async fn native_oidc_start_login(state: &AppState, params: &HashMap<String, String>) -> Response {
    let mode = params.get("mode").map(|s| s.as_str()).unwrap_or("login");

    if mode == "link" {
        // Link mode requires an existing session; the session is checked in the
        // caller (root_get passes the session), but start_login itself doesn't
        // need it. We just redirect to the OIDC provider with mode=link in the
        // encrypted state. The callback will verify the session.
    }

    let config = state.config();
    match fm_oidc::start_login(config).await {
        Ok(redirect) => Redirect::to(&redirect.auth_url).into_response(),
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: mode.to_string(),
                email: None,
                error: Some(err.to_string()),
                reauth_required: false,
            };
            (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response()
        }
    }
}

/// Handles `?LoginOIDC&code=…&state=…` — the OIDC provider's redirect callback.
async fn native_oidc_login(
    state: &AppState,
    _uri: &Uri,
    params: &HashMap<String, String>,
    session: &fm_session::Session,
    original_action: &str,
) -> Response {
    let config = state.config();

    let encrypted_state = params.get("state").map(|s| s.as_str()).unwrap_or("");
    let code = params.get("code").map(|s| s.as_str()).unwrap_or("");

    // Handle provider error (e.g. access_denied)
    if let Some(error) = params.get("error") {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: None,
            error: Some(error.clone()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    if encrypted_state.is_empty() || code.is_empty() {
        let base = config.base_url.trim_end_matches('/');
        let _ = base;
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: None,
            error: Some("OIDC: missing code or state parameter".to_string()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    let callback_result = match fm_oidc::handle_callback(config, encrypted_state, code).await {
        Ok(result) => result,
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: None,
                error: Some(err.to_string()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    if !callback_result.ok {
        let payload: fm_oidc::OidcCallbackPayload = callback_result.into();
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    // Successful callback — now branch on login vs link mode.
    let mode = callback_result.mode.clone();
    let Some(provider_hash) = callback_result.provider_hash.clone() else {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: mode.clone(),
            email: callback_result.email.clone(),
            error: Some("OIDC: provider hash missing".to_string()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    };

    let Some(subject) = callback_result.subject.clone() else {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: mode.clone(),
            email: callback_result.email.clone(),
            error: Some("OIDC: subject missing".to_string()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    };

    let Some(pool) = state.db_pool() else {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: mode.clone(),
            email: callback_result.email.clone(),
            error: Some("Frickmail database is not configured".to_string()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    };

    if mode == "link" {
        native_oidc_link_identity(state, pool, session, &provider_hash, &subject, &callback_result).await
    } else {
        native_oidc_establish_session(state, pool, session, &provider_hash, &subject, &callback_result, original_action).await
    }
}

/// Link mode: user is already authenticated. Store the OIDC identity and
/// encrypt the credential key for escrow.
async fn native_oidc_link_identity(
    state: &AppState,
    pool: &sqlx::AnyPool,
    session: &fm_session::Session,
    provider_hash: &str,
    subject: &str,
    callback_result: &fm_oidc::OidcCallbackResult,
) -> Response {
    let Some(user) = (match load_session_user(state, "StartLoginOIDC", session).await {
        Ok(user) => user,
        Err(response) => return response,
    }) else {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "link".to_string(),
            email: callback_result.email.clone(),
            error: Some("You must be logged in with your Frickmail password before linking an OIDC identity".to_string()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    };

    // Get the credential key from the session.
    let credential_key = match load_session_credential_key("StartLoginOIDC", session).await {
        Ok(key) => key,
        Err(response) => return response,
    };

    // Upsert the OIDC identity linking this user.
    if let Err(err) = SqlxUserRepository::upsert_oidc_identity(
        pool, user.user_id, provider_hash, subject,
    )
    .await
    {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "link".to_string(),
            email: callback_result.email.clone(),
            error: Some(err.public_message()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    // Encrypt the credential key and store it as the escrow key.
    let salt = state.config().app_salt.as_deref().unwrap_or("");
    let encrypted = fm_oidc::encrypt_escrow_key(&credential_key, salt);
    if let Err(err) = SqlxUserRepository::set_oidc_escrow_key(pool, user.user_id, &encrypted).await {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "link".to_string(),
            email: callback_result.email.clone(),
            error: Some(err.public_message()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    // Success — render the callback page so the popup closes.
    let payload = fm_oidc::OidcCallbackPayload {
        ok: true,
        mode: "link".to_string(),
        email: callback_result.email.clone(),
        error: None,
        reauth_required: false,
    };
    (
        StatusCode::OK,
        [("content-type", "text/html; charset=utf-8")],
        fm_oidc::render_callback(&payload),
    )
        .into_response()
}

/// Login mode: look up the OIDC identity, decrypt the escrow key, establish
/// the session, and bridge IMAP.
async fn native_oidc_establish_session(
    state: &AppState,
    pool: &sqlx::AnyPool,
    session: &fm_session::Session,
    provider_hash: &str,
    subject: &str,
    callback_result: &fm_oidc::OidcCallbackResult,
    original_action: &str,
) -> Response {
    // Look up the OIDC identity to find the user.
    let user_id = match SqlxUserRepository::find_oidc_identity(pool, provider_hash, subject).await {
        Ok(Some(id)) => id,
        Ok(None) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(
                    "No Frickmail account is linked to this OIDC identity. \
                     Log in with your Frickmail password first, then link your \
                     OIDC account from Settings."
                        .to_string(),
                ),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(err.public_message()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    // Decrypt the escrow key to recover the credential key.
    let escrow_blob = match SqlxUserRepository::get_oidc_escrow_key(pool, user_id).await {
        Ok(Some(blob)) => blob,
        Ok(None) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(
                    "OIDC escrow key missing — log in with your Frickmail password \
                     and re-link OIDC from Settings."
                        .to_string(),
                ),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(err.public_message()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    let salt = state.config().app_salt.as_deref().unwrap_or("");
    let credential_key = match fm_oidc::decrypt_escrow_key(&escrow_blob, salt) {
        Some(key) if key.len() == CREDENTIAL_KEY_BYTES => key,
        _ => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(
                    "OIDC escrow key could not be decrypted — the server APP_SALT \
                     may have changed. Please re-link OIDC from Settings."
                        .to_string(),
                ),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    // Look up the user for session establishment.
    let user = match SqlxUserRepository::find_by_id(pool, user_id).await {
        Ok(Some(user)) => user,
        Ok(None) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some("OIDC identity user not found".to_string()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(err.public_message()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    // Establish the Frickmail session.
    if let Err(err) = session.cycle_id().await {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: callback_result.email.clone(),
            error: Some(format!("Frickmail session rotation failed: {err}")),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    if let Err(err) = session
        .insert(
            fm_session::USER_SESSION_KEY,
            fm_core::UserSession {
                user_id: user.id,
                username: user.username.clone(),
                email: user.email.clone(),
            },
        )
        .await
    {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: callback_result.email.clone(),
            error: Some(format!("Frickmail session write failed: {err}")),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    let encoded_key = STANDARD.encode(&credential_key);
    if let Err(err) = session
        .insert(
            fm_session::CREDENTIAL_KEY_SESSION_KEY,
            encoded_key,
        )
        .await
    {
        let _ = session
            .remove::<fm_core::UserSession>(fm_session::USER_SESSION_KEY)
            .await;
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: callback_result.email.clone(),
            error: Some(format!("Frickmail session write failed: {err}")),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    // Bridge IMAP using the primary mail account.
    let account = match SqlxUserRepository::get_primary_mail_account(pool, user.id).await {
        Ok(Some(account)) => account,
        Ok(None) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: true,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: None,
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(err.public_message()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    let validation = match mail_account_connection_secret_to_validation(
        pool, user_id, &account, &credential_key,
    )
    .await
    {
        Ok(validation) => validation,
        Err(err) => {
            let payload = fm_oidc::OidcCallbackPayload {
                ok: false,
                mode: "login".to_string(),
                email: callback_result.email.clone(),
                error: Some(err.public_message()),
                reauth_required: false,
            };
            return (
                StatusCode::OK,
                [("content-type", "text/html; charset=utf-8")],
                fm_oidc::render_callback(&payload),
            )
                .into_response();
        }
    };

    // Validate the IMAP connection (like native_frickmail_login does).
    let bridge_result = validate_mail_account_bridge_live(validation).await;
    let reauth_required = match &bridge_result {
        Ok(_) => false,
        Err(err) => {
            // Auth errors (expired/incorrect password, missing OAuth token)
            // require the user to re-enter credentials in the main window.
            let msg = err.public_message().to_lowercase();
            msg.contains("re-authorize")
                || msg.contains("auth")
                || msg.contains("login")
                || msg.contains("credential")
                || msg.contains("password")
        }
    };

    if reauth_required {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: true,
            mode: "login".to_string(),
            email: callback_result.email.clone(),
            error: None,
            reauth_required: true,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    if let Err(err) = bridge_result {
        let payload = fm_oidc::OidcCallbackPayload {
            ok: false,
            mode: "login".to_string(),
            email: callback_result.email.clone(),
            error: Some(err.public_message()),
            reauth_required: false,
        };
        return (
            StatusCode::OK,
            [("content-type", "text/html; charset=utf-8")],
            fm_oidc::render_callback(&payload),
        )
            .into_response();
    }

    // Success! Store the selected account in the session.
    if let Err(_err) = store_selected_mail_account(session, original_action, account.id).await {
        // Continue anyway — the session is established, the bridge is just a nicety.
    }

    // Establish the connection token so the main window can use the bridged session.
    if let Err(_err) = ensure_connection_token(state, session, Some(account.id)).await {
        // Continue anyway.
    }

    let payload = fm_oidc::OidcCallbackPayload {
        ok: true,
        mode: "login".to_string(),
        email: callback_result.email.clone(),
        error: None,
        reauth_required: false,
    };
    (
        StatusCode::OK,
        [("content-type", "text/html; charset=utf-8")],
        fm_oidc::render_callback(&payload),
    )
        .into_response()
}

/// Builds a MailAccountBridgeValidation from the user's primary mail account,
/// used during OIDC login to probe the IMAP connection.
async fn mail_account_connection_secret_to_validation(
    pool: &sqlx::AnyPool,
    user_id: i64,
    account: &MailAccount,
    credential_key: &[u8],
) -> fm_core::Result<MailAccountBridgeValidation> {
    let secret = SqlxUserRepository::get_mail_account_connection_secret(
        pool, user_id, account.id,
    )
    .await?
    .ok_or_else(|| {
        FrickmailError::BadRequest("Primary mail account not found".to_string())
    })?;

    mail_account_bridge_validation(&secret, credential_key)
}

async fn json_api(
    State(state): State<AppState>,
    session: fm_session::Session,
    OriginalUri(uri): OriginalUri,
    request: AxumRequest,
) -> Response {
    json_api_request(state, uri, request, session).await
}

async fn json_api_request(
    state: AppState,
    uri: Uri,
    request: AxumRequest,
    session: fm_session::Session,
) -> Response {
    let (parts, body) = request.into_parts();
    let method = parts.method;
    let headers = parts.headers;
    let query = query_map(&uri);
    let route_action = legacy_route_action(&uri);
    let native_upload =
        legacy_upload_service_route(&uri) && state.config().php_bridge_url.is_none();
    if native_upload {
        match load_session_user(&state, "Upload", &session).await {
            Ok(Some(_)) => {}
            Ok(None) => return legacy_upload_error("Upload", 1, "Not authenticated"),
            Err(response) => return response,
        }
    }
    let body_limit = if native_upload {
        COMPOSE_ATTACHMENT_LIMIT_BYTES + COMPOSE_UPLOAD_REQUEST_OVERHEAD_BYTES
    } else {
        JSON_BODY_LIMIT_BYTES
    };
    // Multipart parsing materializes a selected file alongside the collected
    // request body. Admit that worst-case pair before reading the body and keep
    // the permit through quota inspection and atomic staging. The body deadline
    // ensures slow clients cannot retain shared compose memory indefinitely.
    let (body, _native_upload_memory_permit) = if native_upload {
        match legacy_collect_native_upload_body(
            body,
            body_limit,
            Arc::clone(compose_attachment_memory_semaphore()),
            Duration::from_secs(10),
            COMPOSE_UPLOAD_BODY_DEADLINE,
        )
        .await
        {
            Ok((body, permit)) => (body, Some(permit)),
            Err(message) => return legacy_upload_error("Upload", 1, message),
        }
    } else {
        let body = match to_bytes(body, body_limit).await {
            Ok(body) => body,
            Err(err) => {
                return json_value_envelope(
                    StatusCode::OK,
                    "",
                    compat_error(
                        INVALID_INPUT_ARGUMENT,
                        format!("Invalid or oversized request body: {err}"),
                    ),
                )
            }
        };
        (body, None)
    };

    let request = match plugin_request_from_http(&query, &headers, &body, route_action) {
        Ok(request) => {
            let request = attach_legacy_json_raw_key(request, &uri);
            if state.config().security.csrf_enabled
                && method == Method::POST
                && normalize_plugin_action(&request.action).is_ok()
                && !is_logout_payload(&request.payload)
            {
                if let Err(response) =
                    enforce_connection_token(&state, &session, &headers, &request.payload).await
                {
                    return response;
                }
            }
            if let Some(response) = bridge_json_request(
                &state,
                &method,
                &uri,
                &headers,
                body.clone(),
                &request.action,
            )
            .await
            {
                return response;
            }
            request
        }
        Err(error) => return json_value_envelope(StatusCode::OK, "", error),
    };

    let action = match normalize_plugin_action(&request.action) {
        Ok(action) => action.to_string(),
        Err(error) => {
            return json_value_envelope(
                StatusCode::OK,
                &request.action,
                compat_error(INVALID_INPUT_ARGUMENT, action_error_message(error)),
            )
        }
    };

    if action == "Upload" {
        if !native_upload {
            return legacy_upload_error(
                &request.action,
                1,
                "Native uploads require the /?/Upload/ service route",
            );
        }
        return native_legacy_upload(
            &state,
            &request.action,
            &request.payload,
            &headers,
            &body,
            &session,
        )
        .await;
    }

    if action == "FolderAppend" {
        return native_legacy_folder_append_multipart(
            &state,
            &request.action,
            &headers,
            &body,
            &session,
        )
        .await;
    }

    if action == "AttachmentsActions"
        && payload_optional_string(&request.payload, "target")
            .is_some_and(|target| target.eq_ignore_ascii_case("zip"))
    {
        return match tokio::time::timeout(
            ATTACHMENT_EXPORT_DEADLINE,
            native_legacy_attachments_actions(&state, &request.action, &request.payload, &session),
        )
        .await
        {
            Ok(response) => response,
            Err(_) => json_result_error(&request.action, "Attachment archive export timed out"),
        };
    }

    if is_compat_hook(&action) {
        if let Some(response) = native_compat_response(
            &state,
            &action,
            &request.action,
            &request.payload,
            &session,
            &headers,
            &body,
        )
        .await
        {
            return response;
        }

        let response = bridge_unimplemented(PluginRequest {
            action: action.clone(),
            payload: request.payload,
        });
        return json_value_envelope(StatusCode::OK, &request.action, response);
    }

    json_value_envelope(
        StatusCode::OK,
        &request.action,
        compat_error(
            UNKNOWN_ERROR,
            format!("Frickmail action '{}' is not registered", request.action),
        ),
    )
}

async fn legacy_collect_native_upload_body(
    body: Body,
    body_limit: usize,
    memory_semaphore: Arc<Semaphore>,
    admission_deadline: Duration,
    body_deadline: Duration,
) -> Result<(Bytes, tokio::sync::OwnedSemaphorePermit), String> {
    let permit = tokio::time::timeout(
        admission_deadline,
        memory_semaphore.acquire_many_owned(COMPOSE_UPLOAD_MEMORY_PERMIT_UNITS),
    )
    .await
    .map_err(|_| "Attachment memory budget is busy; retry later".to_string())?
    .map_err(|_| "Attachment memory budget is unavailable".to_string())?;
    let bytes = tokio::time::timeout(body_deadline, to_bytes(body, body_limit))
        .await
        .map_err(|_| "Upload body timed out".to_string())?
        .map_err(|err| format!("Invalid or oversized upload request: {err}"))?;
    Ok((bytes, permit))
}

fn is_legacy_json_request(uri: &Uri) -> bool {
    uri.query()
        .is_some_and(|query| query.starts_with("/Json/") || query.starts_with("?/Json/"))
}

fn query_map(uri: &Uri) -> HashMap<String, String> {
    uri.query()
        .and_then(|query| serde_urlencoded::from_str(query).ok())
        .unwrap_or_default()
}

fn legacy_json_action(uri: &Uri) -> Option<String> {
    let query = uri.query()?;
    if !is_legacy_json_request(uri) {
        return None;
    }

    let action = query
        .split_once("/0/")
        .map(|(_, tail)| tail)
        .unwrap_or_default()
        .trim_start_matches('/');
    let action = action.split(['/', '&']).next().unwrap_or_default().trim();

    if action.is_empty() {
        None
    } else {
        Some(action.to_string())
    }
}

fn legacy_route_action(uri: &Uri) -> Option<String> {
    if let Some(action) = legacy_json_action(uri) {
        return Some(action);
    }

    if legacy_upload_service_route(uri) {
        Some("Upload".to_string())
    } else {
        None
    }
}

/// The legacy client downloads an archive immediately after `AttachmentsActions`
/// through this exact service-query shape.  Keep it narrow so JSON and ordinary
/// Raw attachment routes retain their existing bridge/compatibility behavior.
fn legacy_attachment_export_download_route(uri: &Uri) -> Option<&str> {
    const PREFIX: &str = "/Raw/&q[]=/0/Download/&q[]=/";
    uri.query()?
        .strip_prefix(PREFIX)
        .filter(|raw_key| !raw_key.is_empty() && !raw_key.contains('&'))
}

fn legacy_upload_service_route(uri: &Uri) -> bool {
    if is_legacy_json_request(uri) {
        return false;
    }
    uri.query()
        .is_some_and(|query| query.starts_with("/Upload/"))
}

fn legacy_admin_app_data_route(uri: &Uri) -> Option<bool> {
    let query = uri.query()?;
    if query.starts_with("/AppData/0/") {
        Some(false)
    } else if query.starts_with("/AdminAppData/0/") {
        Some(true)
    } else {
        None
    }
}

async fn fallback() -> Response {
    error_response(FrickmailError::NotFound("route".to_string()))
}

fn error_response(error: FrickmailError) -> Response {
    let status = error.status();
    let body = ErrorBody {
        result: false,
        error_message: error.public_message(),
    };
    (status, Json(body)).into_response()
}

async fn bridge_json_request(
    state: &AppState,
    method: &Method,
    uri: &Uri,
    headers: &HeaderMap,
    body: Bytes,
    action: &str,
) -> Option<Response> {
    let bridge_url = state.config().php_bridge_url.as_deref()?;
    let target = match bridge_target_url(bridge_url, uri) {
        Ok(target) => target,
        Err(err) => {
            return Some(json_value_envelope(
                StatusCode::OK,
                action,
                compat_error(UNKNOWN_ERROR, format!("Invalid PHP bridge URL: {err}")),
            ))
        }
    };

    let response = state
        .bridge_client()
        .request(method.clone(), target)
        .headers(forward_headers(headers))
        .body(body)
        .send()
        .await;

    let response = match response {
        Ok(response) => response,
        Err(err) => {
            return Some(json_value_envelope(
                StatusCode::OK,
                action,
                compat_error(UNKNOWN_ERROR, format!("PHP bridge request failed: {err}")),
            ))
        }
    };

    let status = response.status();
    let content_type = response.headers().get(CONTENT_TYPE).cloned();
    let set_cookies = response
        .headers()
        .get_all(SET_COOKIE)
        .iter()
        .cloned()
        .collect::<Vec<_>>();
    let body = match response.bytes().await {
        Ok(body) => body,
        Err(err) => {
            return Some(json_value_envelope(
                StatusCode::OK,
                action,
                compat_error(UNKNOWN_ERROR, format!("PHP bridge response failed: {err}")),
            ))
        }
    };

    let mut builder = Response::builder().status(status);
    if let Some(content_type) = content_type {
        builder = builder.header(CONTENT_TYPE, content_type);
    }
    for cookie in set_cookies {
        builder = builder.header(SET_COOKIE, cookie);
    }

    Some(
        builder
            .body(axum::body::Body::from(body))
            .unwrap_or_else(|err| {
                json_value_envelope(
                    StatusCode::OK,
                    action,
                    compat_error(UNKNOWN_ERROR, format!("PHP bridge response failed: {err}")),
                )
            }),
    )
}

