async fn native_frickmail_me(
    state: &AppState,
    original_action: &str,
    session: &fm_session::Session,
) -> Response {
    let result = match load_session_user(state, original_action, session).await {
        Ok(Some(user_session)) => FrickmailMe::from_session(&user_session),
        Ok(None) => FrickmailMe::anonymous(),
        Err(response) => return response,
    };

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": result
        }),
    )
}

async fn native_hibp_check(
    state: &AppState,
    original_action: &str,
    session: &fm_session::Session,
) -> Response {
    let Some(user) = (match load_session_user(state, original_action, session).await {
        Ok(user) => user,
        Err(response) => return response,
    }) else {
        return json_result_error(original_action, "Not authenticated");
    };

    let Some(pool) = state.db_pool() else {
        return json_result_error(original_action, "Frickmail database is not configured");
    };

    let credential_key = match load_session_credential_key(original_action, session).await {
        Ok(credential_key) => credential_key,
        Err(response) => return response,
    };

    let selected = match session
        .get::<fm_core::SelectedMailAccountSession>(fm_session::SELECTED_ACCOUNT_SESSION_KEY)
        .await
    {
        Ok(Some(selected)) if selected.account_id > 0 => selected,
        Ok(_) => return json_result_error(original_action, "No account selected"),
        Err(err) => {
            return json_result_error(
                original_action,
                &format!("Frickmail session read failed: {err}"),
            )
        }
    };

    let secret = match fm_user::SqlxUserRepository::get_mail_account_connection_secret(
        pool,
        user.user_id,
        selected.account_id,
    )
    .await
    {
        Ok(Some(secret)) => secret,
        Ok(None) => return json_result_error(original_action, "Account not found"),
        Err(err) => return json_result_error(original_action, &err.public_message()),
    };

    let password = match secret.encrypted_password.as_deref() {
        Some(blob) => match fm_user::decrypt_account_secret(blob, &credential_key) {
            Ok(Some(password)) => password,
            Ok(None) => {
                return json_result_error(original_action, "Account password not available")
            }
            Err(err) => return json_result_error(original_action, &err.public_message()),
        },
        None => return json_result_error(original_action, "Account password not available"),
    };

    let pwned = match hibp_check_password(&password).await {
        Ok(count) => count,
        Err(message) => return json_result_error(original_action, &message),
    };

    let api_key = state.config().hibp.api_key.as_deref().unwrap_or("");
    let breaches = if api_key.is_empty() {
        None
    } else {
        hibp_check_account(api_key, &hibp_ascii_email(&secret.email)).await
    };

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": {
                "pwned": pwned,
                "breaches": breaches
            }
        }),
    )
}

fn legacy_password_strength(password: &str) -> u32 {
    let bytes = password.as_bytes();
    let length = bytes.len();
    let max = (length as u32).saturating_mul(8).min(100);
    let mut variation_score = 0_f64;
    for index in 1..length {
        if bytes[index] != bytes[index - 1] {
            variation_score += 1.0;
        } else {
            variation_score -= 0.5;
        }
    }

    let class_patterns: [regex::Regex; 4] = [
        regex::Regex::new(r"[^0-9A-Za-z]+").unwrap(),
        regex::Regex::new(r"[0-9]+").unwrap(),
        regex::Regex::new(r"[A-Z]+").unwrap(),
        regex::Regex::new(r"[a-z]+").unwrap(),
    ];
    let mut classes = 0_u32;
    for pattern in &class_patterns {
        if pattern.is_match(password) {
            classes += 1;
            if pattern
                .find_iter(password)
                .all(|part| part.as_str().len() < 5)
            {
                variation_score += 1.0;
            }
        }
    }

    let score = variation_score * f64::from(classes) * 1.5;
    if score < 0.0 {
        0
    } else {
        (score as u32).min(max)
    }
}

const SEARCH_FILTER_PLUGIN_NAME: &str = "Search Filters";
const SEARCH_FILTER_SETTINGS_KEY: &str = "SFilters";

enum SearchFilterPriority {
    Number(f64),
    String(String),
    Null,
}

fn search_filter_priority_kind(value: &Value) -> SearchFilterPriority {
    match value {
        Value::Number(number) => SearchFilterPriority::Number(number.as_f64().unwrap_or_default()),
        Value::Bool(enabled) => SearchFilterPriority::Number(u8::from(*enabled).into()),
        Value::String(text) => text.trim().parse::<f64>().map_or_else(
            |_| SearchFilterPriority::String(text.trim().to_string()),
            SearchFilterPriority::Number,
        ),
        _ => SearchFilterPriority::Null,
    }
}

fn search_filter_priority_equals(stored: &Value, submitted: &Value) -> bool {
    match (
        search_filter_priority_kind(stored),
        search_filter_priority_kind(submitted),
    ) {
        (SearchFilterPriority::Null, other) | (other, SearchFilterPriority::Null) => match other {
            SearchFilterPriority::Number(0.0) => true,
            SearchFilterPriority::String(text) => text.is_empty(),
            _ => false,
        },
        (SearchFilterPriority::Number(left), SearchFilterPriority::Number(right)) => left == right,
        (SearchFilterPriority::String(left), SearchFilterPriority::String(right)) => left == right,
        _ => false,
    }
}

fn search_filter_priority_less_or_equal(stored: &Value, submitted: &Value) -> bool {
    let stored = search_filter_priority_kind(stored);
    let submitted = search_filter_priority_kind(submitted);
    let number = |value| match value {
        SearchFilterPriority::Null => Some(0.0),
        SearchFilterPriority::String(text) if text.is_empty() => Some(0.0),
        SearchFilterPriority::Number(number) if number.is_finite() => Some(number),
        _ => None,
    };
    number(stored).is_some_and(|stored| stored >= number(submitted).unwrap_or_default())
}

fn search_filter_from_value(value: &Value) -> Option<Value> {
    let object = value.as_object()?;
    let query = object.get("searchQ")?.as_str()?.trim();
    if query.is_empty() || !object.get("fFolder").is_some_and(Value::is_string) {
        return None;
    }
    Some(json!({
        "searchQ": query,
        "priority": object.get("priority").unwrap_or(&Value::Null),
        "fFolder": object["fFolder"],
        "fSeen": legacy_php_truthy(
            object
                .get("fSeen")
                .unwrap_or(&Value::Bool(false)),
        ),
        "fFlag": legacy_php_truthy(
            object
                .get("fFlag")
                .unwrap_or(&Value::Bool(false)),
        ),
    }))
}

async fn load_search_filters(
    state: &AppState,
    original_action: &str,
    session: &fm_session::Session,
) -> Result<(sqlx::AnyPool, Vec<Value>), Response> {
    let Some(user) = (match load_session_user(state, original_action, session).await {
        Ok(user) => user,
        Err(response) => return Err(response),
    }) else {
        return Err(json_result_error(original_action, "Not authenticated"));
    };
    let Some(pool) = state.db_pool().cloned() else {
        return Err(json_result_error(
            original_action,
            "Frickmail database is not configured",
        ));
    };

    let settings = match SqlxUserRepository::find_by_id(&pool, user.user_id).await {
        Ok(Some(user)) => user.settings,
        Ok(None) => return Err(json_result_error(original_action, "Not authenticated")),
        Err(err) => return Err(json_result_error(original_action, &err.public_message())),
    };
    let filters = settings
        .get("Plugins")
        .and_then(|plugins| plugins.get(SEARCH_FILTER_PLUGIN_NAME))
        .and_then(|plugin| plugin.get(SEARCH_FILTER_SETTINGS_KEY))
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    Ok((pool, filters))
}

async fn save_search_filters_for_plugin(
    pool: &sqlx::AnyPool,
    user_id: i64,
    mut plugin_settings: serde_json::Map<String, Value>,
    filters: Vec<Value>,
) -> fm_core::Result<()> {
    plugin_settings.insert(SEARCH_FILTER_SETTINGS_KEY.to_string(), json!(filters));
    SqlxUserRepository::replace_user_settings_key(
        pool,
        user_id,
        "Plugins",
        &json!({
            SEARCH_FILTER_PLUGIN_NAME: Value::Object(plugin_settings),
        }),
    )
    .await
}

async fn native_search_filters_get(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let (_, filters) = match load_search_filters(state, original_action, session).await {
        Ok(result) => result,
        Err(response) => return response,
    };
    let result = match payload_string(payload, "SSearchQ") {
        Some(search_query) => {
            let selected = filters
                .iter()
                .rev()
                .find(|filter| {
                    filter.get("searchQ").and_then(Value::as_str) == Some(search_query.as_str())
                })
                .cloned()
                .unwrap_or(Value::Null);
            json!({"SFilter": selected})
        }
        None => json!({"SFilters": filters}),
    };
    json_value_envelope(StatusCode::OK, original_action, json!({"Result": result}))
}

async fn mutate_search_filters<F>(
    state: &AppState,
    original_action: &str,
    _payload: &Value,
    session: &fm_session::Session,
    mutation: F,
) -> Response
where
    F: FnOnce(Vec<Value>) -> Option<Vec<Value>>,
{
    let (pool, filters) = match load_search_filters(state, original_action, session).await {
        Ok(result) => result,
        Err(response) => return response,
    };
    let Some(updated) = mutation(filters) else {
        return json_result_error(original_action, "Invalid filter");
    };
    let Some(user) = (match load_session_user(state, original_action, session).await {
        Ok(user) => user,
        Err(response) => return response,
    }) else {
        return json_result_error(original_action, "Not authenticated");
    };
    let settings = match SqlxUserRepository::find_by_id(&pool, user.user_id).await {
        Ok(Some(user)) => user.settings,
        Ok(None) => return json_result_error(original_action, "Not authenticated"),
        Err(err) => return json_result_error(original_action, &err.public_message()),
    };
    let plugin_settings = settings
        .get("Plugins")
        .and_then(|plugins| plugins.get(SEARCH_FILTER_PLUGIN_NAME))
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    match save_search_filters_for_plugin(&pool, user.user_id, plugin_settings, updated).await {
        Ok(()) => json_value_envelope(StatusCode::OK, original_action, json!({"Result": true})),
        Err(err) => json_result_error(original_action, &err.public_message()),
    }
}

async fn native_search_filters_add_edit(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let Some(new_filter) = payload.get("SFilter").and_then(search_filter_from_value) else {
        return json_result_error(original_action, "Invalid filter");
    };
    mutate_search_filters(state, original_action, payload, session, |mut filters| {
        let query = new_filter["searchQ"].as_str().unwrap_or_default();
        if query.is_empty() {
            return None;
        }
        filters.retain(|filter| {
            filter.get("searchQ").and_then(Value::as_str) != Some(query)
                || search_filter_priority_equals(
                    filter.get("priority").unwrap_or(&Value::Null),
                    &new_filter["priority"],
                )
        });
        if let Some(index) = filters
            .iter()
            .position(|filter| filter.get("searchQ").and_then(Value::as_str) == Some(query))
        {
            filters[index] = new_filter.clone();
            return Some(filters);
        }

        let mut insert_index = 0_usize;
        for (index, filter) in filters.iter().enumerate() {
            if search_filter_priority_less_or_equal(
                filter.get("priority").unwrap_or(&Value::Null),
                &new_filter["priority"],
            ) {
                insert_index = index + 1;
            } else {
                break;
            }
        }
        filters.insert(insert_index, new_filter.clone());
        Some(filters)
    })
    .await
}

async fn native_search_filters_update(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let input = payload.get("SFilter").cloned().unwrap_or(Value::Null);
    mutate_search_filters(state, original_action, payload, session, |mut filters| {
        let old_query = input["oldSearchQ"].as_str().unwrap_or_default();
        let Some(new_query) = input["searchQ"]
            .as_str()
            .map(str::trim)
            .filter(|v| !v.is_empty())
        else {
            return Some(filters);
        };
        if let Some(filter) = filters
            .iter_mut()
            .find(|filter| filter.get("searchQ").and_then(Value::as_str) == Some(old_query))
        {
            if let Some(object) = filter.as_object_mut() {
                object.insert("searchQ".to_string(), Value::String(new_query.to_string()));
            }
        }
        Some(filters)
    })
    .await
}

async fn native_search_filters_delete(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let search_query = payload_string(payload, "SSearchQ").unwrap_or_default();
    mutate_search_filters(state, original_action, payload, session, move |filters| {
        Some(
            filters
                .into_iter()
                .filter(|filter| {
                    filter.get("searchQ").and_then(Value::as_str) != Some(search_query.as_str())
                })
                .collect(),
        )
    })
    .await
}

async fn native_change_password(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let config = state.config().change_password.clone();
    if !config.enabled {
        return legacy_action_error(
            original_action,
            CHANGE_PASSWORD_FAILED,
            "Password change is unavailable",
        );
    }

    let Some(user_session) = (match load_session_user(state, original_action, session).await {
        Ok(user) => user,
        Err(response) => return response,
    }) else {
        return json_result_error(original_action, "Not authenticated");
    };
    if user_session
        .email
        .as_deref()
        .unwrap_or_default()
        .trim()
        .is_empty()
    {
        return legacy_action_error(
            original_action,
            CHANGE_PASSWORD_FAILED,
            "Change password failed",
        );
    }

    let Some(pool) = state.db_pool() else {
        return json_result_error(original_action, "Frickmail database is not configured");
    };

    let current_password = payload_string(payload, "PrevPassword").unwrap_or_default();
    let new_password = payload_string(payload, "NewPassword").unwrap_or_default();
    if new_password.len() < usize::try_from(config.pass_min_length).unwrap_or(usize::MAX) {
        return legacy_action_error(
            original_action,
            NEW_PASSWORD_SHORT,
            "New password is too short",
        );
    }
    if config.pass_min_strength > legacy_password_strength(&new_password) {
        return legacy_action_error(
            original_action,
            NEW_PASSWORD_WEAK,
            "New password is too weak",
        );
    }
    if config.check_hibp {
        let pwned_count = match hibp_check_password(&new_password).await {
            Ok(count) => count,
            Err(message) => {
                return json_result_error(
                    original_action,
                    &format!("Password breach check unavailable: {message}"),
                );
            }
        };
        if pwned_count > 0 {
            return legacy_action_error(
                original_action,
                NEW_PASSWORD_HIBP,
                "Password has been breached",
            );
        }
    }

    match fm_user::SqlxUserRepository::change_login_password(
        pool,
        user_session.user_id,
        &current_password,
        new_password,
    )
    .await
    {
        Ok(true) => {}
        Ok(false) => {
            return legacy_action_error(
                original_action,
                CHANGE_PASSWORD_FAILED,
                "Change password failed",
            );
        }
        Err(FrickmailError::Unauthorized) => {
            return legacy_action_error(
                original_action,
                CURRENT_PASSWORD_INCORRECT,
                "Current password is incorrect",
            );
        }
        Err(err) => return json_result_error(original_action, &err.public_message()),
    }

    if let Err(err) = session.cycle_id().await {
        return json_result_error(
            original_action,
            &format!("Frickmail session rotation failed: {err}"),
        );
    }
    if let Err(err) = session
        .remove::<String>(fm_session::CREDENTIAL_KEY_SESSION_KEY)
        .await
    {
        return json_result_error(
            original_action,
            &format!("Frickmail credential session reset failed: {err}"),
        );
    }

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": true
        }),
    )
}

/// Check a password against the Have I Been Pwned Pwned Passwords API (k-anonymity model).
/// Returns the breach count, or an error when HIBP could not provide an answer.
/// An unavailable upstream must never be reported as a reassuring zero.
async fn hibp_check_password(password: &str) -> Result<i64, String> {
    let hash = hex::encode(Sha1::digest(password.as_bytes())).to_uppercase();
    let prefix = &hash[..5];
    let suffix = &hash[5..];

    let url = format!("https://api.pwnedpasswords.com/range/{prefix}");
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .user_agent("frickmail-hibp")
        .build()
    {
        Ok(client) => client,
        Err(err) => return Err(format!("HIBP password check unavailable: {err}")),
    };

    let body = match client.get(&url).header("Add-Padding", "true").send().await {
        Ok(response) if response.status().is_success() => match response.text().await {
            Ok(text) => text,
            Err(err) => return Err(format!("HIBP password check unavailable: {err}")),
        },
        Ok(response) => {
            return Err(format!(
                "HIBP password check unavailable: HTTP {}",
                response.status()
            ))
        }
        Err(err) => return Err(format!("HIBP password check unavailable: {err}")),
    };

    for line in body.lines() {
        if let Some((hash_suffix, count)) = line.split_once(':') {
            if hash_suffix.eq_ignore_ascii_case(suffix) {
                return count
                    .trim()
                    .parse::<i64>()
                    .map_err(|_| "HIBP password check returned an invalid count".to_string());
            }
        }
    }

    Ok(0)
}

fn hibp_ascii_email(email: &str) -> String {
    let Some((local, domain)) = email.trim().rsplit_once('@') else {
        return email.trim().to_string();
    };
    match idna::domain_to_ascii(domain) {
        Ok(domain) => format!("{local}@{domain}"),
        Err(_) => email.trim().to_string(),
    }
}

/// Check an email address against the Have I Been Pwned Breached Account API.
/// Returns the list of breaches, or None if the request fails.
async fn hibp_check_account(api_key: &str, email: &str) -> Option<Vec<serde_json::Value>> {
    let encoded_email = percent_encode_email(email);
    let url = format!(
        "https://haveibeenpwned.com/api/v3/breachedaccount/{}",
        encoded_email
    );

    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .user_agent("frickmail-hibp")
        .build()
    {
        Ok(client) => client,
        Err(_) => return None,
    };

    let response = match client
        .get(&url)
        .header("hibp-api-key", api_key)
        .send()
        .await
    {
        Ok(response) => response,
        Err(_) => return None,
    };

    if response.status().as_u16() == 404 {
        return Some(Vec::new());
    }

    if !response.status().is_success() {
        return None;
    }

    response.json::<Vec<serde_json::Value>>().await.ok()
}

const SEND_MESSAGE_SMTP_DEADLINE: Duration = Duration::from_secs(120);
const SEND_MESSAGE_ACTION_DEADLINE: Duration = Duration::from_secs(240);
const SEND_MESSAGE_DRAFT_CLEANUP_DEADLINE: Duration = Duration::from_secs(30);
const SEND_PHASE_PRE_SMTP: u8 = 0;
const SEND_PHASE_SMTP_IN_FLIGHT: u8 = 1;
