#[derive(Debug, Clone)]
struct LegacyComposeStagingScope {
    root: PathBuf,
    user_directory: PathBuf,
    directory: PathBuf,
    account_id: i64,
}

impl LegacyComposeStagingScope {
    fn new(tmp_dir: &str, user_id: i64, account_id: i64) -> Self {
        Self::in_namespace(tmp_dir, "compose-attachments", user_id, account_id)
    }

    fn attachment_export(tmp_dir: &str, user_id: i64, account_id: i64) -> Self {
        Self::in_namespace(tmp_dir, "attachment-exports", user_id, account_id)
    }

    fn in_namespace(tmp_dir: &str, namespace: &str, user_id: i64, account_id: i64) -> Self {
        let root = Path::new(tmp_dir).join(namespace);
        let user_directory = root.join(format!("user-{user_id:x}"));
        let directory = user_directory.join(format!("account-{account_id:x}"));
        Self {
            root,
            user_directory,
            directory,
            account_id,
        }
    }

    fn path(&self, token: &str) -> Option<PathBuf> {
        legacy_compose_attachment_token_is_valid(token).then(|| self.directory.join(token))
    }
}

async fn legacy_prepare_compose_staging_scope(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<()> {
    let scope = scope.clone();
    tokio::task::spawn_blocking(move || legacy_prepare_compose_staging_scope_sync(&scope))
        .await
        .map_err(|err| std::io::Error::other(format!("staging directory task failed: {err}")))?
}

async fn legacy_validate_compose_staging_scope(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<bool> {
    let scope = scope.clone();
    tokio::task::spawn_blocking(move || legacy_validate_compose_staging_scope_sync(&scope))
        .await
        .map_err(|err| std::io::Error::other(format!("staging validation task failed: {err}")))?
}

#[cfg(unix)]
fn legacy_prepare_compose_staging_scope_sync(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<()> {
    use std::os::unix::fs::{DirBuilderExt, MetadataExt, PermissionsExt};

    // SAFETY: geteuid has no preconditions and does not dereference pointers.
    let current_uid = unsafe { libc::geteuid() };
    let base = scope
        .root
        .parent()
        .ok_or_else(|| std::io::Error::other("attachment staging root has no parent"))?;

    let ensure_created = |path: &Path| -> std::io::Result<()> {
        let mut builder = std::fs::DirBuilder::new();
        builder.mode(0o700);
        match builder.create(path) {
            Ok(()) => Ok(()),
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => Ok(()),
            Err(err) => Err(err),
        }
    };

    if std::fs::symlink_metadata(base).is_err_and(|err| err.kind() == std::io::ErrorKind::NotFound)
    {
        ensure_created(base)?;
    }
    let base_metadata = std::fs::symlink_metadata(base)?;
    if base_metadata.file_type().is_symlink() || !base_metadata.is_dir() {
        return Err(std::io::Error::other(
            "attachment staging base must be a real directory",
        ));
    }
    let base_mode = base_metadata.mode();
    let trusted_system_base =
        base_metadata.uid() == 0 && (base_mode & 0o022 == 0 || base_mode & 0o1000 != 0);
    if base_metadata.uid() != current_uid && !trusted_system_base {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "attachment staging base has an untrusted owner or permissions",
        ));
    }
    if legacy_should_tighten_staging_base(current_uid, base_metadata.uid(), base_mode) {
        std::fs::set_permissions(base, std::fs::Permissions::from_mode(0o700))?;
    }

    for directory in [&scope.root, &scope.user_directory, &scope.directory] {
        ensure_created(directory)?;
        let metadata = std::fs::symlink_metadata(directory)?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() || metadata.uid() != current_uid
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                format!(
                    "attachment staging directory is not private and owned: {}",
                    directory.display()
                ),
            ));
        }
        std::fs::set_permissions(directory, std::fs::Permissions::from_mode(0o700))?;
    }
    Ok(())
}

#[cfg(unix)]
fn legacy_should_tighten_staging_base(current_uid: u32, owner_uid: u32, mode: u32) -> bool {
    owner_uid == current_uid && !(current_uid == 0 && (mode & 0o022 == 0 || mode & 0o1000 != 0))
}

#[cfg(unix)]
fn legacy_validate_compose_staging_scope_sync(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<bool> {
    use std::os::unix::fs::{MetadataExt, PermissionsExt};

    // SAFETY: geteuid has no preconditions and does not dereference pointers.
    let current_uid = unsafe { libc::geteuid() };
    let base = scope
        .root
        .parent()
        .ok_or_else(|| std::io::Error::other("attachment staging root has no parent"))?;
    let base_metadata = match std::fs::symlink_metadata(base) {
        Ok(metadata) => metadata,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(err) => return Err(err),
    };
    if base_metadata.file_type().is_symlink() || !base_metadata.is_dir() {
        return Err(std::io::Error::other(
            "attachment staging base must be a real directory",
        ));
    }
    let base_mode = base_metadata.permissions().mode();
    let trusted_system_base =
        base_metadata.uid() == 0 && (base_mode & 0o022 == 0 || base_mode & 0o1000 != 0);
    if base_metadata.uid() != current_uid && !trusted_system_base {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "attachment staging base has an untrusted owner or permissions",
        ));
    }

    for directory in [&scope.root, &scope.user_directory, &scope.directory] {
        let metadata = match std::fs::symlink_metadata(directory) {
            Ok(metadata) => metadata,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(false),
            Err(err) => return Err(err),
        };
        if metadata.file_type().is_symlink()
            || !metadata.is_dir()
            || metadata.uid() != current_uid
            || metadata.permissions().mode() & 0o077 != 0
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                format!(
                    "attachment staging directory is not private and owned: {}",
                    directory.display()
                ),
            ));
        }
    }
    Ok(true)
}

#[cfg(not(unix))]
fn legacy_prepare_compose_staging_scope_sync(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<()> {
    std::fs::create_dir_all(&scope.directory)
}

#[cfg(not(unix))]
fn legacy_validate_compose_staging_scope_sync(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<bool> {
    match std::fs::symlink_metadata(&scope.directory) {
        Ok(metadata) => Ok(metadata.is_dir() && !metadata.file_type().is_symlink()),
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(err) => Err(err),
    }
}

#[derive(Debug, Clone)]
struct LegacyComposeAttachmentSpec {
    token: String,
    file_name: String,
    is_inline: bool,
    content_id: String,
    content_location: String,
    mime_type: String,
    is_linked: bool,
}

#[derive(Debug)]
struct LegacyComposeAttachment {
    spec: LegacyComposeAttachmentSpec,
    data: Vec<u8>,
}

/// Legacy `SendMessage` compose payload after validation.
struct LegacySendMessageRequest {
    /// Full `From:` header value, display name included.
    from: String,
    /// Bare address used as the SMTP envelope sender.
    envelope_from: String,
    to: Vec<String>,
    cc: Vec<String>,
    bcc: Vec<String>,
    reply_to: Vec<String>,
    subject: String,
    /// Sanitized, canonical, size-bounded HTML document.
    html: String,
    plain: String,
    in_reply_to: String,
    references: String,
    read_receipt_request: bool,
    mark_as_important: bool,
    dsn: bool,
    require_tls: bool,
    autocrypt: Option<LegacyAutocryptHeader>,
    attachments: Vec<LegacyComposeAttachment>,
    _attachment_memory_permit: Option<tokio::sync::OwnedSemaphorePermit>,
    save_folder: String,
    draft_folder: String,
    draft_uid: u32,
    draft_info: Option<LegacyDraftInfoRequest>,
    /// `Some(identityID)` requests the legacy exact `sign=S/MIME` flow.
    smime_sign_identity: Option<String>,
    smime_direct_signing: Option<LegacyDirectSmimeSigning>,
    /// S/MIME encryption recipient certificate IDs or PEM strings
    smime_encrypt_certificates: Vec<String>,
    /// OpenPGP signed MIME content (pre-built by client, e.g. Mailvelope)
    pgp_signed: Option<String>,
    /// OpenPGP encrypted data (pre-built by client, e.g. Mailvelope)
    pgp_encrypted: Option<String>,
    /// MIME boundary for pgp_signed multipart/signed structure
    pgp_boundary: Option<String>,
    /// Server-side GnuPG signing key requested by the legacy client.
    gnupg_sign_fingerprint: Option<String>,
    /// Server-side GnuPG signing passphrase; never included in Debug output.
    gnupg_sign_passphrase: Option<String>,
    /// Server-side GnuPG recipient fingerprints.
    gnupg_encrypt_fingerprints: Vec<String>,
}

impl std::fmt::Debug for LegacySendMessageRequest {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("LegacySendMessageRequest")
            .field("from", &self.from)
            .field("envelope_from", &self.envelope_from)
            .field("to", &self.to)
            .field("cc", &self.cc)
            .field("bcc", &self.bcc)
            .field("reply_to", &self.reply_to)
            .field("subject", &self.subject)
            .field("attachments", &self.attachments.len())
            .field("save_folder", &self.save_folder)
            .field("draft_folder", &self.draft_folder)
            .field("draft_uid", &self.draft_uid)
            .finish_non_exhaustive()
    }
}

struct LegacyDirectSmimeSigning {
    certificate_pem: String,
    private_key_pem: String,
    passphrase: String,
}

impl std::fmt::Debug for LegacyDirectSmimeSigning {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("LegacyDirectSmimeSigning { material: [redacted] }")
    }
}

/// Validated legacy Autocrypt header values. Key material is stored as
/// canonical padded Base64 so serialization never copies caller
/// supplied whitespace or control characters into an RFC 5322 header.
#[derive(Debug, Clone, PartialEq, Eq)]
struct LegacyAutocryptHeader {
    addr: String,
    keydata: String,
}

#[derive(Clone)]
struct LegacyPgpAttachmentDisposition;

impl lettre::message::header::Header for LegacyPgpAttachmentDisposition {
    fn name() -> lettre::message::header::HeaderName {
        lettre::message::header::HeaderName::new_from_ascii_str("Content-Disposition")
    }

    fn parse(_value: &str) -> Result<Self, Box<dyn std::error::Error + Send + Sync>> {
        Ok(Self)
    }

    fn display(&self) -> lettre::message::header::HeaderValue {
        lettre::message::header::HeaderValue::new(Self::name(), "attachment".to_string())
    }
}

/// Final compose body after HTML sanitation and optional PHP-compatible plain
/// fallback derivation. The combined serialized content is size-bounded before
/// this value leaves the dedicated blocking-work admission boundary.
#[derive(Debug)]
struct LegacyNormalizedComposeBody {
    html: String,
    plain: String,
    inline_attachments: Vec<LegacyComposeAttachment>,
    _attachment_memory_permit: Option<tokio::sync::OwnedSemaphorePermit>,
}

/// `draftInfo` triple: [type, uid, folder]. Drives the reply/forward flag update.
#[derive(Debug)]
struct LegacyDraftInfoRequest {
    info_type: String,
    uid: u32,
    folder: String,
}

