async fn native_legacy_attachments_actions_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: Fn(ImapConnectionConfig, String, String, u32, String) -> Fut,
    Fut: std::future::Future<Output = fm_core::Result<Option<Vec<u8>>>>,
{
    let (scope, config, password) =
        match legacy_attachment_export_imap_context(state, original_action, payload, session).await
        {
            Ok(connection) => connection,
            Err(response) => return response,
        };
    let target = payload_optional_string(payload, "target").unwrap_or_default();
    if !target.eq_ignore_ascii_case("zip") {
        return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
    }

    let requested_filename = payload_optional_string(payload, "filename").unwrap_or_default();
    let folder = payload_optional_string(payload, "folder").unwrap_or_default();
    let hashes = match payload.get("hashes") {
        Some(Value::Array(arr)) if !arr.is_empty() && arr.len() <= ATTACHMENT_EXPORT_MAX_ITEMS => {
            arr
        }
        _ => {
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        }
    };
    let raw_key_bytes = hashes.iter().try_fold(0_usize, |total, hash| {
        let value = hash.as_str()?;
        (value.len() <= COMPOSE_ATTACHMENT_RAW_KEY_LIMIT_BYTES)
            .then_some(total.saturating_add(value.len()))
    });
    if raw_key_bytes.is_none_or(|bytes| bytes > COMPOSE_ATTACHMENT_RAW_KEY_TOTAL_LIMIT_BYTES) {
        return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
    }

    let _export_permit = match tokio::time::timeout(
        Duration::from_secs(10),
        Arc::clone(attachment_export_semaphore()).acquire_owned(),
    )
    .await
    {
        Ok(Ok(permit)) => permit,
        _ => {
            return json_result_error(
                original_action,
                "Attachment archive export is busy; retry later",
            )
        }
    };
    if let Err(err) = legacy_prepare_compose_staging_scope(&scope).await {
        tracing::warn!("Could not secure attachment export directory: {err}");
        return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
    }
    let usage = match legacy_cleanup_attachment_exports(&scope).await {
        Ok(usage) => usage,
        Err(err) => {
            tracing::warn!("Could not inspect attachment export quota: {err}");
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        }
    };
    if ATTACHMENT_EXPORT_ARCHIVE_LIMIT_BYTES
        > ATTACHMENT_EXPORT_GLOBAL_LIMIT_BYTES.saturating_sub(usage.global_bytes)
        || ATTACHMENT_EXPORT_ARCHIVE_LIMIT_BYTES
            > ATTACHMENT_EXPORT_USER_LIMIT_BYTES.saturating_sub(usage.user_bytes)
        || usage.global_files >= ATTACHMENT_EXPORT_GLOBAL_FILE_LIMIT
        || usage.user_files >= ATTACHMENT_EXPORT_USER_FILE_LIMIT
    {
        return json_result_error(
            original_action,
            "Attachment archive export quota is full; retry later",
        );
    }

    let archive_token = legacy_random_compose_attachment_token();
    let mut source_paths = LegacyAttachmentExportSources::default();
    let mut input_bytes = 0_usize;
    for (index, hash) in hashes.iter().enumerate() {
        let Some(raw_values) = legacy_raw_key_json(hash.as_str().unwrap_or_default()) else {
            legacy_remove_attachment_export_sources(&source_paths.0).await;
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        };
        let file_name = raw_values
            .get("fileName")
            .and_then(Value::as_str)
            .filter(|name| {
                !name.is_empty() && name.len() <= COMPOSE_ATTACHMENT_FILENAME_LIMIT_BYTES
            })
            .unwrap_or("file.dat")
            .to_string();
        let source_uid = raw_values
            .get("uid")
            .and_then(Value::as_u64)
            .and_then(|uid| u32::try_from(uid).ok());
        let source_is_mime_part = raw_values
            .get("mimeIndex")
            .and_then(Value::as_str)
            .is_some_and(legacy_compose_string_is_php_truthy);
        let data = if let Some(data_b64) = raw_values.get("data").and_then(Value::as_str) {
            URL_SAFE_NO_PAD
                .decode(data_b64.as_bytes())
                .or_else(|_| URL_SAFE.decode(data_b64.as_bytes()))
                .ok()
        } else {
            let item_folder = raw_values
                .get("folder")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty() && value.len() <= 1024)
                .unwrap_or(&folder);
            let item_uid = raw_values
                .get("uid")
                .and_then(Value::as_u64)
                .and_then(|uid| u32::try_from(uid).ok())
                .unwrap_or(0);
            let mime_index = raw_values
                .get("mimeIndex")
                .and_then(Value::as_str)
                .filter(|value| value.len() <= 256)
                .unwrap_or_default()
                .to_string();
            if item_uid == 0 || item_folder.is_empty() {
                None
            } else {
                let _memory_permit = match tokio::time::timeout(
                    Duration::from_secs(10),
                    Arc::clone(compose_attachment_memory_semaphore())
                        .acquire_many_owned(compose_attachment_fetch_memory_permit_units()),
                )
                .await
                {
                    Ok(Ok(permit)) => permit,
                    _ => {
                        legacy_remove_attachment_export_sources(&source_paths.0).await;
                        return json_result_error(
                            original_action,
                            "Attachment export memory budget is busy; retry later",
                        );
                    }
                };
                match tokio::time::timeout(
                    fetch_deadline,
                    fetcher(
                        config.clone(),
                        password.clone(),
                        item_folder.to_string(),
                        item_uid,
                        mime_index,
                    ),
                )
                .await
                {
                    Ok(Ok(Some(data))) => Some(data),
                    Ok(Ok(None)) | Err(_) => None,
                    Ok(Err(err)) => {
                        tracing::warn!("Failed to fetch attachment for ZIP export: {err}");
                        None
                    }
                }
            }
        };
        let Some(data) = data else {
            legacy_remove_attachment_export_sources(&source_paths.0).await;
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        };
        if data.len() > COMPOSE_ATTACHMENT_LIMIT_BYTES
            || data.len() > ATTACHMENT_EXPORT_INPUT_LIMIT_BYTES.saturating_sub(input_bytes)
        {
            legacy_remove_attachment_export_sources(&source_paths.0).await;
            return json_result_error(
                original_action,
                "Attachment archive exceeds its bounded input limit",
            );
        }
        input_bytes += data.len();
        let source_path = scope
            .directory
            .join(format!(".{archive_token}.{index}.source"));
        if let Err(err) = legacy_write_private_temporary_file(&source_path, &data).await {
            legacy_remove_attachment_export_sources(&source_paths.0).await;
            tracing::warn!("Could not stage attachment export source: {err}");
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        }
        source_paths
            .0
            .push((file_name, source_uid, source_is_mime_part, source_path));
    }

    if source_paths.0.is_empty() {
        return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
    }
    let archive_path = scope
        .path(&archive_token)
        .expect("generated archive token is valid");
    let partial_path = scope.directory.join(format!(".{archive_token}.partial"));
    let archive_result = tokio::task::spawn_blocking({
        let source_paths = source_paths;
        let partial_path = partial_path.clone();
        let archive_path = archive_path.clone();
        let folder = folder.clone();
        let export_permit = _export_permit;
        move || {
            let result = create_zip_archive_file(
                &partial_path,
                &source_paths.0,
                &folder,
                ATTACHMENT_EXPORT_ARCHIVE_LIMIT_BYTES,
            )
            .and_then(|()| {
                std::fs::rename(&partial_path, &archive_path)?;
                Ok(())
            });
            if result.is_err() {
                let _ = std::fs::remove_file(&partial_path);
            }
            drop(source_paths);
            drop(export_permit);
            result
        }
    })
    .await;
    match archive_result {
        Ok(Ok(())) => {}
        Ok(Err(err)) => {
            tracing::warn!("Failed to create bounded ZIP archive: {err}");
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        }
        Err(err) => {
            tracing::error!("ZIP compression task failed: {err}");
            return json_value_envelope(StatusCode::OK, original_action, json!({"Result": false}));
        }
    }
    let zip_filename =
        legacy_attachment_export_visible_filename(&requested_filename, &folder, Local::now());

    let raw_key_value = json!({
        "fileName": zip_filename,
        "mimeType": "application/zip",
        "fileHash": archive_token,
        "accountId": legacy_attachment_export_account_id(&scope),
    });

    let json_str = serde_json::to_string(&raw_key_value)
        .map_err(|err| {
            tracing::error!("Failed to serialize attachment raw key: {err}");
        })
        .unwrap_or_default();
    let encoded = URL_SAFE_NO_PAD.encode(json_str);

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": {
                "fileHash": encoded
            }
        }),
    )
}

#[cfg(test)]
fn create_zip_archive(
    files: &[(String, Vec<u8>)],
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    let buf = std::io::Cursor::new(Vec::new());
    let mut zip = zip::ZipWriter::new(buf);
    let options = zip::write::SimpleFileOptions::default()
        .compression_method(zip::CompressionMethod::Deflated);

    let mut seen_names: HashMap<String, u32> = HashMap::new();
    for (name, data) in files {
        // Strip any directory components so the entry name cannot escape the
        // extraction directory (prevents zip-slip / path-traversal writes).
        let safe_name = legacy_safe_zip_entry_name(name);
        // Disambiguate duplicate basenames by appending a numeric suffix,
        // preventing `zip::ZipWriter::start_file` from erroring on
        // collisions when two attachments share the same filename.
        let final_name = match seen_names.get(safe_name.as_str()) {
            Some(&count) => {
                let (stem, extension) = match safe_name.rsplit_once('.') {
                    Some((s, ext)) if !s.is_empty() && !ext.is_empty() => (s, Some(ext)),
                    _ => (safe_name.as_str(), None),
                };
                let suffixed = match extension {
                    Some(ext) => format!("{stem}_{count}.{ext}"),
                    None => format!("{stem}_{count}"),
                };
                seen_names.insert(safe_name.clone(), count + 1);
                suffixed
            }
            None => {
                seen_names.insert(safe_name.clone(), 1);
                safe_name
            }
        };
        zip.start_file(final_name, options)?;
        std::io::Write::write_all(&mut zip, data)?;
    }

    Ok(zip.finish()?.into_inner())
}

struct LimitedZipWriter {
    file: std::fs::File,
    limit: usize,
}

impl std::io::Write for LimitedZipWriter {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        let position = usize::try_from(self.file.stream_position()?).unwrap_or(usize::MAX);
        if bytes.len() > self.limit.saturating_sub(position) {
            return Err(std::io::Error::other(
                "ZIP archive exceeds the configured size limit",
            ));
        }
        self.file.write(bytes)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.file.flush()
    }
}

impl std::io::Seek for LimitedZipWriter {
    fn seek(&mut self, position: std::io::SeekFrom) -> std::io::Result<u64> {
        self.file.seek(position)
    }
}

fn create_zip_archive_file(
    output_path: &Path,
    files: &[(String, Option<u32>, bool, PathBuf)],
    folder: &str,
    max_bytes: usize,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    use std::io::{Read as _, Write as _};

    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let file = options.open(output_path)?;
    let writer = LimitedZipWriter {
        file,
        limit: max_bytes,
    };
    let mut zip = zip::ZipWriter::new(writer);
    let options = zip::write::SimpleFileOptions::default()
        .compression_method(zip::CompressionMethod::Deflated);
    let mut seen_names: HashMap<String, u32> = HashMap::new();
    let mut buffer = [0_u8; 64 * 1024];

    let mime_uids = files
        .iter()
        .filter_map(|(_, uid, is_mime_part, _)| is_mime_part.then_some(*uid).flatten())
        .collect::<HashSet<_>>();
    let group_by_uid = mime_uids.len() > 1;
    for (name, uid, _, source_path) in files {
        let safe_name = legacy_safe_zip_entry_name(name);
        let final_name = match uid {
            Some(uid) if group_by_uid => format!("{uid}/{safe_name}"),
            Some(uid) if !folder.is_empty() => format!("{uid}-{safe_name}"),
            _ => safe_name,
        };
        let final_name = legacy_unique_zip_entry_name(&final_name, &mut seen_names);
        zip.start_file(final_name, options)?;
        let mut source = std::fs::File::open(source_path)?;
        loop {
            let read = source.read(&mut buffer)?;
            if read == 0 {
                break;
            }
            zip.write_all(&buffer[..read])?;
        }
    }
    zip.finish()?.flush()?;
    Ok(())
}

fn legacy_unique_zip_entry_name(name: &str, seen_names: &mut HashMap<String, u32>) -> String {
    match seen_names.get(name) {
        Some(&count) => {
            let (stem, extension) = match name.rsplit_once('.') {
                Some((stem, extension)) if !stem.is_empty() && !extension.is_empty() => {
                    (stem, Some(extension))
                }
                _ => (name, None),
            };
            let suffixed = match extension {
                Some(extension) => format!("{stem}_{count}.{extension}"),
                None => format!("{stem}_{count}"),
            };
            seen_names.insert(name.to_string(), count + 1);
            suffixed
        }
        None => {
            seen_names.insert(name.to_string(), 1);
            name.to_string()
        }
    }
}

fn legacy_safe_zip_entry_name(value: &str) -> String {
    let name = value.rsplit(['/', '\\']).next().unwrap_or_default();
    let name = name
        .chars()
        .filter(|character| !character.is_control())
        .collect::<String>();
    if name.is_empty() || matches!(name.as_str(), "." | "..") {
        "file.dat".to_string()
    } else {
        name
    }
}

async fn legacy_write_private_temporary_file(path: &Path, data: &[u8]) -> std::io::Result<()> {
    let mut options = tokio::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600);
    let mut file = options.open(path).await?;
    if let Err(err) = file.write_all(data).await {
        let _ = tokio::fs::remove_file(path).await;
        return Err(err);
    }
    if let Err(err) = file.flush().await {
        let _ = tokio::fs::remove_file(path).await;
        return Err(err);
    }
    Ok(())
}

async fn legacy_remove_attachment_export_sources(sources: &[(String, Option<u32>, bool, PathBuf)]) {
    for (_, _, _, path) in sources {
        if let Err(err) = tokio::fs::remove_file(path).await {
            if err.kind() != std::io::ErrorKind::NotFound {
                tracing::warn!(
                    "Could not remove temporary ZIP source {}: {err}",
                    path.display()
                );
            }
        }
    }
}

#[derive(Default)]
struct LegacyAttachmentExportSources(Vec<(String, Option<u32>, bool, PathBuf)>);

impl Drop for LegacyAttachmentExportSources {
    fn drop(&mut self) {
        for (_, _, _, path) in &self.0 {
            let _ = std::fs::remove_file(path);
        }
    }
}

#[derive(Debug, Default)]
struct AttachmentExportUsage {
    global_bytes: usize,
    user_bytes: usize,
    global_files: usize,
    user_files: usize,
}

async fn legacy_cleanup_attachment_exports(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<AttachmentExportUsage> {
    let mut usage = AttachmentExportUsage::default();
    let mut directories = vec![scope.root.clone()];
    let mut pending = vec![scope.root.clone()];
    let cutoff = SystemTime::now() - ATTACHMENT_EXPORT_MAX_AGE;
    while let Some(directory) = pending.pop() {
        let mut entries = match tokio::fs::read_dir(&directory).await {
            Ok(entries) => entries,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => continue,
            Err(err) => return Err(err),
        };
        while let Some(entry) = entries.next_entry().await? {
            let kind = entry.file_type().await?;
            if kind.is_dir() {
                if directories.len() >= COMPOSE_ATTACHMENT_GLOBAL_DIRECTORY_LIMIT {
                    return Err(std::io::Error::other(
                        "attachment export directory limit exceeded",
                    ));
                }
                let path = entry.path();
                directories.push(path.clone());
                pending.push(path);
                continue;
            }
            if !kind.is_file() {
                continue;
            }
            let metadata = entry.metadata().await?;
            if metadata.modified().is_ok_and(|modified| modified < cutoff)
                && tokio::fs::remove_file(entry.path()).await.is_ok()
            {
                continue;
            }
            let size = usize::try_from(metadata.len()).unwrap_or(usize::MAX);
            usage.global_bytes = usage.global_bytes.saturating_add(size);
            usage.global_files = usage.global_files.saturating_add(1);
            if entry.path().starts_with(&scope.user_directory) {
                usage.user_bytes = usage.user_bytes.saturating_add(size);
                usage.user_files = usage.user_files.saturating_add(1);
            }
            if usage.global_bytes > ATTACHMENT_EXPORT_GLOBAL_LIMIT_BYTES
                || usage.user_bytes > ATTACHMENT_EXPORT_USER_LIMIT_BYTES
                || usage.global_files > ATTACHMENT_EXPORT_GLOBAL_FILE_LIMIT
                || usage.user_files > ATTACHMENT_EXPORT_USER_FILE_LIMIT
            {
                return Err(std::io::Error::other("attachment export quota exceeded"));
            }
        }
    }
    directories.sort_by_key(|path| std::cmp::Reverse(path.components().count()));
    for directory in directories {
        if directory != scope.root
            && directory != scope.user_directory
            && directory != scope.directory
        {
            let _ = tokio::fs::remove_dir(directory).await;
        }
    }
    Ok(usage)
}

fn legacy_attachment_export_account_id(scope: &LegacyComposeStagingScope) -> i64 {
    scope.account_id
}

fn legacy_attachment_export_filename(value: &str) -> String {
    let mut output = value
        .chars()
        .filter(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | '-')
        })
        .take(180)
        .collect::<String>();
    if output.is_empty() {
        output = "attachments".to_string();
    }
    output
}

fn legacy_attachment_export_visible_filename(
    value: &str,
    folder: &str,
    now: chrono::DateTime<Local>,
) -> String {
    let stem = if value.is_empty() {
        if folder.is_empty() {
            "attachments".to_string()
        } else {
            "messages".to_string()
        }
    } else {
        legacy_attachment_export_filename(value)
    };
    format!("{}-{}.zip", stem, now.format("%Y%m%d%H%M%S"))
}

async fn native_legacy_attachment_export_download(
    state: &AppState,
    raw_key: &str,
    session: &fm_session::Session,
) -> Response {
    if raw_key.len() > COMPOSE_ATTACHMENT_RAW_KEY_LIMIT_BYTES {
        return StatusCode::NOT_FOUND.into_response();
    }
    let Some(values) = legacy_raw_key_json(raw_key) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let Some(account_id) = values
        .get("accountId")
        .and_then(Value::as_i64)
        .filter(|id| *id > 0)
    else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let Some(token) = values
        .get("fileHash")
        .and_then(Value::as_str)
        .filter(|token| legacy_compose_attachment_token_is_valid(token))
    else {
        return StatusCode::NOT_FOUND.into_response();
    };
    if values.get("mimeType").and_then(Value::as_str) != Some("application/zip") {
        return StatusCode::NOT_FOUND.into_response();
    }
    let Some(user) = (match load_session_user(state, "RawDownload", session).await {
        Ok(user) => user,
        Err(response) => return response,
    }) else {
        return StatusCode::UNAUTHORIZED.into_response();
    };
    let Some(pool) = state.db_pool() else {
        return StatusCode::NOT_FOUND.into_response();
    };
    match SqlxUserRepository::get_mail_account_connection_secret(pool, user.user_id, account_id)
        .await
    {
        Ok(Some(_)) => {}
        _ => return StatusCode::NOT_FOUND.into_response(),
    }
    let scope = LegacyComposeStagingScope::attachment_export(
        &state.config().tmp_dir,
        user.user_id,
        account_id,
    );
    match legacy_validate_compose_staging_scope(&scope).await {
        Ok(true) => {}
        _ => return StatusCode::NOT_FOUND.into_response(),
    }
    let Some(path) = scope.path(token) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let metadata = match tokio::fs::symlink_metadata(&path).await {
        Ok(metadata)
            if metadata.file_type().is_file()
                && metadata.len() <= ATTACHMENT_EXPORT_ARCHIVE_LIMIT_BYTES as u64 =>
        {
            metadata
        }
        _ => return StatusCode::NOT_FOUND.into_response(),
    };
    let download_permit = match tokio::time::timeout(
        Duration::from_secs(10),
        Arc::clone(attachment_export_download_semaphore()).acquire_owned(),
    )
    .await
    {
        Ok(Ok(permit)) => permit,
        _ => return StatusCode::SERVICE_UNAVAILABLE.into_response(),
    };
    let file = match tokio::fs::File::open(&path).await {
        Ok(file) => file,
        Err(_) => return StatusCode::NOT_FOUND.into_response(),
    };
    let filename = values
        .get("fileName")
        .and_then(Value::as_str)
        .map(legacy_attachment_export_filename)
        .unwrap_or_else(|| "attachments.zip".to_string());
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/zip")
        .header(
            "content-disposition",
            format!("attachment; filename=\"{filename}\""),
        )
        .header("content-transfer-encoding", "binary")
        .header("accept-ranges", "none")
        .header("content-length", metadata.len())
        .body(Body::from_stream(futures::stream::try_unfold(
            (file, download_permit),
            |(mut file, permit)| async move {
                let mut buffer = vec![0_u8; 64 * 1024];
                let read = file.read(&mut buffer).await?;
                if read == 0 {
                    Ok::<
                        Option<(Bytes, (tokio::fs::File, tokio::sync::OwnedSemaphorePermit))>,
                        std::io::Error,
                    >(None)
                } else {
                    buffer.truncate(read);
                    Ok(Some((Bytes::from(buffer), (file, permit))))
                }
            },
        )))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

fn legacy_compose_attachment_token_is_valid(token: &str) -> bool {
    token.len() == 40
        && token
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn legacy_random_compose_attachment_token() -> String {
    let mut bytes = [0_u8; 20];
    OsRng.fill_bytes(&mut bytes);
    hex::encode(bytes)
}

async fn legacy_compose_staging_scope_for_payload(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Result<LegacyComposeStagingScope, Response> {
    let (user, _) = imap_action_auth(state, original_action, session).await?;
    let Some(pool) = state.db_pool() else {
        return Err(json_result_error(
            original_action,
            "Frickmail database is not configured",
        ));
    };
    let account_id = resolve_message_body_account_id(payload, session, original_action).await?;
    match SqlxUserRepository::get_mail_account_connection_secret(pool, user.user_id, account_id)
        .await
    {
        Ok(Some(_)) => Ok(LegacyComposeStagingScope::new(
            &state.config().tmp_dir,
            user.user_id,
            account_id,
        )),
        Ok(None) => Err(json_result_error(original_action, "Account not found")),
        Err(err) => Err(json_result_error(original_action, &err.public_message())),
    }
}

async fn legacy_compose_imap_staging_context(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Result<(LegacyComposeStagingScope, ImapConnectionConfig, String), Response> {
    let (user, credential_key) = imap_action_auth(state, original_action, session).await?;
    let Some(pool) = state.db_pool() else {
        return Err(json_result_error(
            original_action,
            "Frickmail database is not configured",
        ));
    };
    // Resolve the selected account once.  Reading it again after an IMAP
    // connection is prepared would allow a concurrent account switch to fetch
    // from one account and stage the bytes under another account's capability
    // directory.
    let account_id = resolve_message_body_account_id(payload, session, original_action).await?;
    let account = match SqlxUserRepository::get_mail_account_connection_secret(
        pool,
        user.user_id,
        account_id,
    )
    .await
    {
        Ok(Some(account)) => account,
        Ok(None) => return Err(json_result_error(original_action, "Account not found")),
        Err(err) => return Err(json_result_error(original_action, &err.public_message())),
    };
    let config = imap_config_from_account_secret(&account)
        .map_err(|err| json_result_error(original_action, &err.public_message()))?;
    let password = account_password(&account, &credential_key)
        .map_err(|_| json_result_error(original_action, "Missing account password"))?;
    let scope = LegacyComposeStagingScope::new(&state.config().tmp_dir, user.user_id, account_id);
    Ok((scope, config, password))
}

async fn legacy_attachment_export_imap_context(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Result<(LegacyComposeStagingScope, ImapConnectionConfig, String), Response> {
    let (user, credential_key) = imap_action_auth(state, original_action, session).await?;
    let Some(pool) = state.db_pool() else {
        return Err(json_result_error(
            original_action,
            "Frickmail database is not configured",
        ));
    };
    let account_id = resolve_message_body_account_id(payload, session, original_action).await?;
    let account = match SqlxUserRepository::get_mail_account_connection_secret(
        pool,
        user.user_id,
        account_id,
    )
    .await
    {
        Ok(Some(account)) => account,
        Ok(None) => return Err(json_result_error(original_action, "Account not found")),
        Err(err) => return Err(json_result_error(original_action, &err.public_message())),
    };
    let config = imap_config_from_account_secret(&account)
        .map_err(|err| json_result_error(original_action, &err.public_message()))?;
    let password = account_password(&account, &credential_key)
        .map_err(|_| json_result_error(original_action, "Missing account password"))?;
    Ok((
        LegacyComposeStagingScope::attachment_export(
            &state.config().tmp_dir,
            user.user_id,
            account_id,
        ),
        config,
        password,
    ))
}

#[derive(Debug, Default)]
struct LegacyComposeStagingUsage {
    global_bytes: usize,
    global_files: usize,
    user_bytes: usize,
    user_files: usize,
    scope_bytes: usize,
    scope_files: usize,
    global_directories: usize,
}

async fn legacy_compose_staging_usage(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<LegacyComposeStagingUsage> {
    legacy_compose_staging_usage_with_max_age(scope, COMPOSE_ATTACHMENT_MAX_AGE).await
}

async fn legacy_compose_staging_usage_with_max_age(
    scope: &LegacyComposeStagingScope,
    max_age: Duration,
) -> std::io::Result<LegacyComposeStagingUsage> {
    legacy_prune_empty_compose_directories(scope).await?;
    let mut usage = LegacyComposeStagingUsage::default();
    let mut pending = vec![scope.root.clone()];
    let mut directories = vec![scope.root.clone()];
    usage.global_directories = 1;
    let cutoff = SystemTime::now() - max_age;

    while let Some(directory) = pending.pop() {
        let mut entries = match tokio::fs::read_dir(&directory).await {
            Ok(entries) => entries,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => continue,
            Err(err) => return Err(err),
        };
        while let Some(entry) = entries.next_entry().await? {
            let file_type = entry.file_type().await?;
            if file_type.is_dir() {
                usage.global_directories = usage.global_directories.saturating_add(1);
                if usage.global_directories > COMPOSE_ATTACHMENT_GLOBAL_DIRECTORY_LIMIT {
                    return Err(std::io::Error::other(
                        "attachment staging directory limit exceeded",
                    ));
                }
                let path = entry.path();
                directories.push(path.clone());
                pending.push(path);
                continue;
            }
            if !file_type.is_file() {
                continue;
            }
            let metadata = entry.metadata().await?;
            if metadata.modified().is_ok_and(|modified| modified < cutoff) {
                match tokio::fs::remove_file(entry.path()).await {
                    Ok(()) => continue,
                    Err(err) => {
                        tracing::warn!(
                            "Failed to remove stale compose attachment {}: {err}",
                            entry.path().display()
                        );
                    }
                }
            }
            let size = usize::try_from(metadata.len()).unwrap_or(usize::MAX);
            usage.global_bytes = usage.global_bytes.saturating_add(size);
            usage.global_files = usage.global_files.saturating_add(1);
            if entry.path().starts_with(&scope.user_directory) {
                usage.user_bytes = usage.user_bytes.saturating_add(size);
                usage.user_files = usage.user_files.saturating_add(1);
            }
            if entry.path().starts_with(&scope.directory) {
                usage.scope_bytes = usage.scope_bytes.saturating_add(size);
                usage.scope_files = usage.scope_files.saturating_add(1);
            }
        }
    }

    directories.sort_by_key(|path| std::cmp::Reverse(path.components().count()));
    for directory in directories {
        if directory == scope.root
            || directory == scope.user_directory
            || directory == scope.directory
        {
            continue;
        }
        match tokio::fs::remove_dir(&directory).await {
            Ok(()) => usage.global_directories = usage.global_directories.saturating_sub(1),
            Err(err)
                if matches!(
                    err.kind(),
                    std::io::ErrorKind::DirectoryNotEmpty | std::io::ErrorKind::NotFound
                ) => {}
            Err(err) => tracing::warn!(
                "Failed to prune empty compose staging directory {}: {err}",
                directory.display()
            ),
        }
    }
    Ok(usage)
}

async fn legacy_prune_empty_compose_directories(
    scope: &LegacyComposeStagingScope,
) -> std::io::Result<()> {
    let mut root_entries = match tokio::fs::read_dir(&scope.root).await {
        Ok(entries) => entries,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(err),
    };
    let mut scanned = 0_usize;
    while scanned < COMPOSE_ATTACHMENT_DIRECTORY_RECOVERY_SCAN_LIMIT {
        let Some(entry) = root_entries.next_entry().await? else {
            break;
        };
        scanned += 1;
        if !entry.file_type().await?.is_dir() {
            continue;
        }
        let directory = entry.path();
        if directory != scope.user_directory && tokio::fs::remove_dir(&directory).await.is_ok() {
            continue;
        }
        let mut children = match tokio::fs::read_dir(&directory).await {
            Ok(children) => children,
            Err(_) => continue,
        };
        while scanned < COMPOSE_ATTACHMENT_DIRECTORY_RECOVERY_SCAN_LIMIT {
            let Some(child) = children.next_entry().await? else {
                break;
            };
            scanned += 1;
            if child.file_type().await?.is_dir() {
                let child = child.path();
                if child != scope.directory {
                    let _ = tokio::fs::remove_dir(child).await;
                }
            }
        }
        drop(children);
        if directory != scope.user_directory {
            let _ = tokio::fs::remove_dir(&directory).await;
        }
    }
    Ok(())
}

async fn legacy_remove_empty_compose_scope(scope: &LegacyComposeStagingScope) {
    for directory in [&scope.directory, &scope.user_directory] {
        if let Err(err) = tokio::fs::remove_dir(directory).await {
            if !matches!(
                err.kind(),
                std::io::ErrorKind::DirectoryNotEmpty | std::io::ErrorKind::NotFound
            ) {
                tracing::warn!(
                    "Failed to prune empty compose staging directory {}: {err}",
                    directory.display()
                );
            }
        }
    }
}

async fn legacy_stage_compose_attachment(
    scope: &LegacyComposeStagingScope,
    token: &str,
    data: &[u8],
    allow_existing: bool,
) -> Result<(), String> {
    if !legacy_compose_attachment_token_is_valid(token) {
        return Err("Invalid attachment token".to_string());
    }
    if data.len() > COMPOSE_ATTACHMENT_LIMIT_BYTES {
        return Err(format!(
            "Attachment exceeds the {} MiB per-file limit",
            COMPOSE_ATTACHMENT_LIMIT_BYTES / 1024 / 1024
        ));
    }

    let _permit = tokio::time::timeout(
        Duration::from_secs(10),
        compose_attachment_staging_semaphore().acquire(),
    )
    .await
    .map_err(|_| "Attachment staging is busy; retry later".to_string())?
    .map_err(|_| "Attachment staging is unavailable".to_string())?;
    legacy_prepare_compose_staging_scope(scope)
        .await
        .map_err(|err| format!("Could not secure attachment staging directory: {err}"))?;

    let target = scope
        .path(token)
        .ok_or_else(|| "Invalid attachment token".to_string())?;
    if allow_existing {
        if let Ok(metadata) = tokio::fs::symlink_metadata(&target).await {
            if metadata.file_type().is_file()
                && usize::try_from(metadata.len()).unwrap_or(usize::MAX)
                    <= COMPOSE_ATTACHMENT_LIMIT_BYTES
            {
                return Ok(());
            }
            return Err("Cached attachment is invalid".to_string());
        }
    } else if tokio::fs::symlink_metadata(&target).await.is_ok() {
        return Err("Attachment token collision".to_string());
    }

    let usage = match legacy_compose_staging_usage(scope).await {
        Ok(usage) => usage,
        Err(err) => {
            legacy_remove_empty_compose_scope(scope).await;
            return Err(format!("Could not inspect attachment staging quota: {err}"));
        }
    };
    if usage.scope_files >= COMPOSE_ATTACHMENT_LIMIT
        || usage.user_files >= COMPOSE_ATTACHMENT_USER_FILE_LIMIT
        || usage.global_files >= COMPOSE_ATTACHMENT_GLOBAL_FILE_LIMIT
        || usage.global_directories >= COMPOSE_ATTACHMENT_GLOBAL_DIRECTORY_LIMIT
        || data.len() > COMPOSE_ATTACHMENT_TOTAL_LIMIT_BYTES.saturating_sub(usage.scope_bytes)
        || data.len() > COMPOSE_ATTACHMENT_USER_LIMIT_BYTES.saturating_sub(usage.user_bytes)
        || data.len() > COMPOSE_ATTACHMENT_GLOBAL_LIMIT_BYTES.saturating_sub(usage.global_bytes)
    {
        legacy_remove_empty_compose_scope(scope).await;
        return Err(format!(
            "Attachment staging exceeds the per-account {} MiB/{} file, per-user {} MiB/{} file, or global {} MiB/{} file/{} directory quota",
            COMPOSE_ATTACHMENT_TOTAL_LIMIT_BYTES / 1024 / 1024,
            COMPOSE_ATTACHMENT_LIMIT,
            COMPOSE_ATTACHMENT_USER_LIMIT_BYTES / 1024 / 1024,
            COMPOSE_ATTACHMENT_USER_FILE_LIMIT,
            COMPOSE_ATTACHMENT_GLOBAL_LIMIT_BYTES / 1024 / 1024,
            COMPOSE_ATTACHMENT_GLOBAL_FILE_LIMIT,
            COMPOSE_ATTACHMENT_GLOBAL_DIRECTORY_LIMIT,
        ));
    }

    let partial = scope.directory.join(format!(
        ".{token}.{}.partial",
        legacy_random_compose_attachment_token()
    ));
    let mut options = tokio::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600);
    let mut file = options
        .open(&partial)
        .await
        .map_err(|err| format!("Could not create staged attachment: {err}"))?;
    if let Err(err) = file.write_all(data).await {
        let _ = tokio::fs::remove_file(&partial).await;
        return Err(format!("Could not write staged attachment: {err}"));
    }
    if let Err(err) = file.flush().await {
        let _ = tokio::fs::remove_file(&partial).await;
        return Err(format!("Could not flush staged attachment: {err}"));
    }
    drop(file);
    if let Err(err) = tokio::fs::rename(&partial, &target).await {
        let _ = tokio::fs::remove_file(&partial).await;
        return Err(format!("Could not finalize staged attachment: {err}"));
    }
    Ok(())
}

async fn legacy_delete_staged_compose_attachments(
    scope: &LegacyComposeStagingScope,
    attachments: &[LegacyComposeAttachment],
) {
    let _permit = match tokio::time::timeout(
        Duration::from_secs(10),
        compose_attachment_staging_semaphore().acquire(),
    )
    .await
    {
        Ok(Ok(permit)) => permit,
        _ => {
            tracing::warn!("Could not acquire attachment staging cleanup admission");
            return;
        }
    };
    for attachment in attachments {
        if let Some(path) = scope.path(&attachment.spec.token) {
            if let Err(err) = tokio::fs::remove_file(&path).await {
                if err.kind() != std::io::ErrorKind::NotFound {
                    tracing::warn!(
                        "Could not remove sent compose attachment {}: {err}",
                        path.display()
                    );
                }
            }
        }
    }
    legacy_remove_empty_compose_scope(scope).await;
}

struct LegacyUploadPart {
    file_name: String,
    mime_type: String,
    data: Vec<u8>,
}

fn legacy_upload_part(content_type: &str, body: &[u8]) -> Option<LegacyUploadPart> {
    multipart_parts(content_type, body)?
        .into_iter()
        .find(|part| multipart_field_name(&part.headers) == Some("uploader"))
        .map(|part| LegacyUploadPart {
            file_name: multipart_disposition_parameter(&part.headers, "filename")
                .unwrap_or_default(),
            mime_type: multipart_header_value(&part.headers, "content-type").unwrap_or_default(),
            data: part.value,
        })
}

async fn native_legacy_upload(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    headers: &HeaderMap,
    body: &[u8],
    session: &fm_session::Session,
) -> Response {
    let scope =
        match legacy_compose_staging_scope_for_payload(state, original_action, payload, session)
            .await
        {
            Ok(scope) => scope,
            Err(response) => return response,
        };
    let content_type = headers
        .get(CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
        .to_string();
    let Some(upload) = legacy_upload_part(&content_type, body) else {
        return legacy_upload_error(original_action, 4, "No file uploaded");
    };
    if upload.data.len() > COMPOSE_ATTACHMENT_LIMIT_BYTES {
        return legacy_upload_error(
            original_action,
            1,
            format!(
                "File exceeds the {} MiB attachment limit",
                COMPOSE_ATTACHMENT_LIMIT_BYTES / 1024 / 1024
            ),
        );
    }
    if legacy_validate_attachment_text(
        &upload.file_name,
        COMPOSE_ATTACHMENT_FILENAME_LIMIT_BYTES,
        false,
    )
    .is_err()
    {
        return legacy_upload_error(original_action, 99, "Invalid attachment filename");
    }

    let token = legacy_random_compose_attachment_token();
    if let Err(message) = legacy_stage_compose_attachment(&scope, &token, &upload.data, false).await
    {
        return legacy_upload_error(original_action, 7, message);
    }
    let mime_type = mime_type_from_hint(&upload.mime_type, &upload.file_name);
    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": {
                "Attachment": {
                    "name": upload.file_name,
                    "tempName": token,
                    "mimeType": mime_type,
                    "size": upload.data.len(),
                }
            }
        }),
    )
}

fn legacy_upload_error(original_action: &str, code: u16, message: impl Into<String>) -> Response {
    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": {
                "code": code,
                "message": message.into(),
            }
        }),
    )
}

#[allow(dead_code)]
async fn native_legacy_message_upload_attachments(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    match tokio::time::timeout(
        MESSAGE_UPLOAD_ATTACHMENTS_ACTION_DEADLINE,
        native_legacy_message_upload_attachments_with_fetcher(
            state,
            original_action,
            payload,
            session,
            MESSAGE_BODY_FETCH_DEADLINE,
            |config, password, folder, uid, mime_index| async move {
                fetch_mime_part_bounded(
                    config,
                    &password,
                    &folder,
                    uid,
                    &mime_index,
                    COMPOSE_ATTACHMENT_LIMIT_BYTES,
                )
                .await
            },
        ),
    )
    .await
    {
        Ok(response) => response,
        Err(_) => json_result_error(original_action, "Attachment upload request timed out"),
    }
}

async fn native_legacy_message_upload_attachments_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: Fn(ImapConnectionConfig, String, String, u32, String) -> Fut + Send + Sync,
    Fut: std::future::Future<Output = fm_core::Result<Option<Vec<u8>>>> + Send,
{
    let (scope, config, password) =
        match legacy_compose_imap_staging_context(state, original_action, payload, session).await {
            Ok(context) => context,
            Err(response) => return response,
        };
    let attachments = match legacy_message_upload_raw_keys(payload) {
        Ok(attachments) => attachments,
        Err(message) => return json_result_error(original_action, &message),
    };
    if attachments.is_empty() {
        return json_value_envelope(StatusCode::OK, original_action, json!({"Result": []}));
    }

    // Independent attachment fetches are parallelized via `FuturesUnordered`
    // up to `COMPOSE_ATTACHMENT_FETCH_CONCURRENCY`, bounded by the IMAP fetch
    // semaphore and the aggregate memory budget. Order is recovered via
    // position tags so results map back to the original attachment list.
    #[allow(clippy::type_complexity)]
    let mut in_flight: FuturesUnordered<
        Pin<Box<dyn std::future::Future<Output = (usize, Value)> + Send + '_>>,
    > = FuturesUnordered::new();

    for (index, attachment) in attachments.iter().enumerate() {
        let raw_key_str = attachment.as_str().unwrap_or_default().to_string();
        let scope = scope.clone();
        let config = config.clone();
        let password = password.clone();
        let fetcher = &fetcher;

        in_flight.push(Box::pin(async move {
            let value = upload_single_attachment(
                &raw_key_str,
                &scope,
                &config,
                &password,
                fetcher,
                fetch_deadline,
            )
            .await;
            (index, value)
        }));
    }

    let mut results = vec![json!(false); attachments.len()];
    while let Some((index, value)) = in_flight.next().await {
        results[index] = value;
    }

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": results
        }),
    )
}

#[allow(clippy::too_many_arguments)]
async fn upload_single_attachment<F, Fut>(
    raw_key_str: &str,
    scope: &LegacyComposeStagingScope,
    config: &ImapConnectionConfig,
    password: &str,
    fetcher: &F,
    fetch_deadline: Duration,
) -> Value
where
    F: Fn(ImapConnectionConfig, String, String, u32, String) -> Fut + Send + Sync,
    Fut: std::future::Future<Output = fm_core::Result<Option<Vec<u8>>>> + Send,
{
    let raw_key_str = raw_key_str.to_string();
    let Some(raw_values) = legacy_raw_key_json(&raw_key_str) else {
        return json!(false);
    };

    let folder = raw_values
        .get("folder")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let uid = raw_values.get("uid").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
    let mime_index = raw_values
        .get("mimeIndex")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let mime_type_hint = raw_values
        .get("mimeType")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let file_name = raw_values
        .get("fileName")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();

    if uid == 0 || folder.is_empty() {
        return json!(false);
    }

    // tempName = sha1(raw_key_string)
    let temp_name = hex::encode(Sha1::digest(raw_key_str.as_bytes()));
    let Some(file_path) = scope.path(&temp_name) else {
        return json!(false);
    };

    // Validate without creating on cache reads. A miss proceeds to
    // the write path, which creates and revalidates private dirs.
    match legacy_validate_compose_staging_scope(scope).await {
        Ok(true) => {
            if let Ok(metadata) = tokio::fs::symlink_metadata(&file_path).await {
                if metadata.file_type().is_file()
                    && usize::try_from(metadata.len()).unwrap_or(usize::MAX)
                        <= COMPOSE_ATTACHMENT_LIMIT_BYTES
                {
                    let mime_type = mime_type_from_hint(&mime_type_hint, &file_name);
                    return json!({
                        "tempName": temp_name,
                        "mimeType": mime_type,
                    });
                }
                return json!(false);
            }
        }
        Ok(false) => {}
        Err(err) => {
            tracing::warn!("Rejected untrusted attachment cache tree: {err}");
            return json!(false);
        }
    }

    // Fetch via IMAP
    let _fetch_permit = match tokio::time::timeout(
        Duration::from_secs(10),
        compose_attachment_fetch_semaphore().acquire(),
    )
    .await
    {
        Ok(Ok(permit)) => permit,
        _ => return json!(false),
    };
    // Hold admission for the four-times decoded quoted-printable wire
    // ceiling (including soft line breaks) plus the decoded staging
    // Vec until the fetch result is written.
    let fetch_memory_units = compose_attachment_fetch_memory_permit_units();
    let _fetch_memory_permit = match tokio::time::timeout(
        Duration::from_secs(10),
        Arc::clone(compose_attachment_memory_semaphore()).acquire_many_owned(fetch_memory_units),
    )
    .await
    {
        Ok(Ok(permit)) => permit,
        _ => return json!(false),
    };
    let data = match tokio::time::timeout(
        fetch_deadline,
        fetcher(
            config.clone(),
            password.to_string(),
            folder,
            uid,
            mime_index,
        ),
    )
    .await
    {
        Ok(Ok(Some(data))) => data,
        Ok(Ok(None)) => {
            return json!(false);
        }
        Ok(Err(err)) => {
            tracing::warn!("Failed to fetch attachment for upload: {err}");
            return json!(false);
        }
        Err(_) => {
            tracing::warn!("Attachment upload fetch timed out");
            return json!(false);
        }
    };

    if let Err(err) = legacy_stage_compose_attachment(scope, &temp_name, &data, true).await {
        tracing::warn!("Failed to stage fetched attachment: {err}");
        return json!(false);
    }

    let mime_type = mime_type_from_hint(&mime_type_hint, &file_name);
    json!({
        "tempName": temp_name,
        "mimeType": mime_type,
    })
}

fn legacy_message_upload_raw_keys(payload: &Value) -> Result<&[Value], String> {
    let Some(Value::Array(attachments)) = payload.get("attachments") else {
        return Ok(&[]);
    };
    if attachments.len() > COMPOSE_ATTACHMENT_LIMIT {
        return Err(format!(
            "Attachment request exceeds the {COMPOSE_ATTACHMENT_LIMIT} file limit"
        ));
    }
    let mut total = 0_usize;
    for raw_key in attachments.iter().filter_map(Value::as_str) {
        if raw_key.len() > COMPOSE_ATTACHMENT_RAW_KEY_LIMIT_BYTES {
            return Err(format!(
                "Attachment key exceeds the {} KiB limit",
                COMPOSE_ATTACHMENT_RAW_KEY_LIMIT_BYTES / 1024
            ));
        }
        total = total
            .checked_add(raw_key.len())
            .ok_or_else(|| "Attachment key size overflow".to_string())?;
        if total > COMPOSE_ATTACHMENT_RAW_KEY_TOTAL_LIMIT_BYTES {
            return Err(format!(
                "Attachment keys exceed the {} KiB aggregate limit",
                COMPOSE_ATTACHMENT_RAW_KEY_TOTAL_LIMIT_BYTES / 1024
            ));
        }
    }
    Ok(attachments)
}

fn mime_type_from_hint(mime_type_hint: &str, file_name: &str) -> String {
    if !mime_type_hint.is_empty() {
        return mime_type_hint.to_string();
    }
    if let Some(ext) = std::path::Path::new(file_name)
        .extension()
        .and_then(|e| e.to_str())
    {
        match ext.to_lowercase().as_str() {
            "pdf" => "application/pdf".to_string(),
            "jpg" | "jpeg" => "image/jpeg".to_string(),
            "png" => "image/png".to_string(),
            "gif" => "image/gif".to_string(),
            "webp" => "image/webp".to_string(),
            "svg" => "image/svg+xml".to_string(),
            "txt" => "text/plain".to_string(),
            "html" | "htm" => "text/html".to_string(),
            "xml" => "application/xml".to_string(),
            "json" => "application/json".to_string(),
            "zip" => "application/zip".to_string(),
            "eml" => "message/rfc822".to_string(),
            "doc" => "application/msword".to_string(),
            "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                .to_string(),
            "xls" => "application/vnd.ms-excel".to_string(),
            "xlsx" => {
                "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet".to_string()
            }
            "ppt" => "application/vnd.ms-powerpoint".to_string(),
            "pptx" => "application/vnd.openxmlformats-officedocument.presentationml.presentation"
                .to_string(),
            "mp3" => "audio/mpeg".to_string(),
            "mp4" => "video/mp4".to_string(),
            "wav" => "audio/wav".to_string(),
            _ => "application/octet-stream".to_string(),
        }
    } else {
        "application/octet-stream".to_string()
    }
}

async fn native_legacy_message(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    headers: &HeaderMap,
) -> Response {
    native_legacy_message_with_fetcher(
        state,
        original_action,
        payload,
        session,
        headers,
        MESSAGE_BODY_FETCH_DEADLINE,
        |config, password, folder, uid| async move {
            fetch_message_body_preview(config, &password, &folder, uid).await
        },
    )
    .await
}

async fn native_legacy_message_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    headers: &HeaderMap,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: FnOnce(ImapConnectionConfig, String, String, u32) -> Fut,
    Fut: std::future::Future<Output = fm_core::Result<Option<Vec<BodyPreviewPart>>>>,
{
    let (config, password) =
        match legacy_imap_connection_context(state, original_action, payload, session).await {
            Ok(connection) => connection,
            Err(response) => return response,
        };
    let (cache_user, _) = match imap_action_auth(state, original_action, session).await {
        Ok(auth) => auth,
        Err(response) => return response,
    };
    let cache_account_id =
        match resolve_message_body_account_id(payload, session, original_action).await {
            Ok(account_id) => account_id,
            Err(response) => return response,
        };
    let message_request = match legacy_message_request_from_payload(payload) {
        Ok(request) => request,
        Err(message) => return json_result_error(original_action, message),
    };
    let client_hash = config.login.clone();

    // Fetch thread data if use_threads is requested
    let (thread_uids, thread_unseen_uids) = if message_request.use_threads
        && !message_request.thread_algorithm.is_empty()
    {
        let folder_hash = legacy_message_list_cache_key(&message_request.folder, &client_hash);

        // Fetch all threads
        let all_threads = match login(config.clone(), &password).await {
            Ok(mut session) => {
                fetch_legacy_message_threads_cached(
                    &mut session,
                    &message_request.thread_algorithm,
                    &folder_hash,
                    None,
                )
                .await
            }
            Err(_) => Vec::new(),
        };

        // Find the thread containing the current message UID
        let thread_uids = all_threads
            .iter()
            .find(|thread| thread.contains(&message_request.uid))
            .cloned()
            .unwrap_or_default();

        let thread_unseen_uids = if message_request.thread_uid > 0 {
            Vec::new()
        } else if !thread_uids.is_empty() {
            // Fetch unseen UIDs for thread_unseen
            match login(config.clone(), &password).await {
                Ok(mut session) => {
                    let _ =
                        timeout_imap("examine mailbox", session.examine(&message_request.folder))
                            .await;
                    let all_unseen = legacy_message_list_visible_uids_cached(
                        &mut session,
                        &message_request.folder,
                        &client_hash,
                        &config.login,
                        "unseen",
                        fm_imap::LegacyMessageListQueryOptions {
                            hide_deleted: true,
                            fast_simple_search: true,
                            permanent_filter: "",
                            sort: None,
                            utf8_mode: false,
                            supports_within: false,
                            supports_literal_plus: false,
                        },
                        None,
                    )
                    .await
                    .unwrap_or_default();
                    // Filter to only unseen UIDs in this thread
                    let thread_set: std::collections::HashSet<u32> =
                        thread_uids.iter().copied().collect();
                    all_unseen
                        .into_iter()
                        .filter(|uid| thread_set.contains(uid))
                        .collect()
                }
                Err(_) => Vec::new(),
            }
        } else {
            Vec::new()
        };
        (thread_uids, thread_unseen_uids)
    } else {
        (Vec::new(), Vec::new())
    };

    let result = tokio::time::timeout(
        fetch_deadline,
        fetcher(
            config,
            password,
            message_request.folder.clone(),
            message_request.uid,
        ),
    )
    .await
    .map_err(|_| FrickmailError::Upstream("Message fetch timed out".to_string()));

    match result {
        Ok(Ok(Some(parts))) => {
            let flags = parts
                .first()
                .map(|part| part.flags.as_slice())
                .unwrap_or(&[]);
            let durable_receipt_suppressed = match state.db_pool() {
                Some(pool) => {
                    legacy_read_receipt_cached(
                        pool,
                        cache_user.user_id,
                        cache_account_id,
                        &message_request.folder,
                        message_request.uid,
                    )
                    .await
                }
                None => Some(false),
            };
            let cache_hash = format!(
                "{client_hash}:rr={}",
                durable_receipt_suppressed
                    .map(|value| value as u8)
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_string())
            );
            let cache_key = legacy_message_cache_key(
                &message_request.folder,
                message_request.uid,
                flags,
                &cache_hash,
            );

            if durable_receipt_suppressed.is_some() {
                if let Some(response) = legacy_http_cache_validation_response(
                    headers,
                    &state.config().cache,
                    &cache_key,
                ) {
                    return response;
                }
            }

            let mut response = legacy_message_body_response(
                original_action,
                &message_request.folder,
                message_request.uid,
                parts,
                &thread_uids,
                &thread_unseen_uids,
                durable_receipt_suppressed.unwrap_or(false),
            );
            if durable_receipt_suppressed.is_some() {
                legacy_apply_http_cache_headers(
                    response.headers_mut(),
                    &state.config().cache,
                    &cache_key,
                );
            }
            response
        }
        Ok(Ok(None)) => json_result_error(original_action, "Message not found"),
        Ok(Err(err)) | Err(err) => json_result_error(original_action, &err.public_message()),
    }
}

fn legacy_message_payload_is_native_candidate(payload: &Value) -> bool {
    (payload.get("folder").is_some() && payload.get("uid").is_some())
        || legacy_message_raw_key_request_from_payload(payload)
            .ok()
            .flatten()
            .is_some()
}

fn legacy_message_request_from_payload(
    payload: &Value,
) -> Result<LegacyMessageRawKeyRequest, &'static str> {
    if let Some(raw_key_request) = legacy_message_raw_key_request_from_payload(payload)? {
        return Ok(raw_key_request);
    }

    let folder = required_payload_string(payload, "folder", "folder required")?;
    let uid = payload_i64(payload, "uid");
    if uid <= 0 || uid > u32::MAX as i64 {
        return Err("uid required");
    }

    Ok(LegacyMessageRawKeyRequest {
        folder,
        uid: uid as u32,
        use_threads: payload_bool(payload, "useThreads"),
        thread_uid: payload_optional_u32(payload, "threadUid").unwrap_or_default(),
        thread_algorithm: payload_string(payload, "threadAlgorithm").unwrap_or_default(),
        account_hash: payload_string(payload, "accountHash").unwrap_or_default(),
    })
}

fn legacy_message_raw_key_request_from_payload(
    payload: &Value,
) -> Result<Option<LegacyMessageRawKeyRequest>, &'static str> {
    let Some(raw_key) = payload_optional_string(payload, "RawKey") else {
        return Ok(None);
    };
    let Some(raw_payload) = legacy_raw_key_json(&raw_key) else {
        return Ok(None);
    };
    let Some(values) = raw_payload.as_array() else {
        return Ok(None);
    };
    if values.len() < 2 {
        return Ok(None);
    }

    let folder = value_to_php_string(&values[0]);
    if folder.is_empty() {
        return Err("folder required");
    }
    let uid = value_to_php_i64(&values[1]);
    if uid <= 0 || uid > u32::MAX as i64 {
        return Err("uid required");
    }

    Ok(Some(LegacyMessageRawKeyRequest {
        folder,
        uid: uid as u32,
        use_threads: values.get(2).map(legacy_php_truthy).unwrap_or(false),
        thread_uid: values.get(4).map(value_to_php_u32).unwrap_or_default(),
        thread_algorithm: values.get(5).map(value_to_php_string).unwrap_or_default(),
        account_hash: values.get(3).map(value_to_php_string).unwrap_or_default(),
    }))
}

async fn native_legacy_message_list(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    headers: &HeaderMap,
) -> Response {
    let redis_pool = state.redis_pool().cloned();
    let fast_cache_index = state.config().cache.fast_cache_index.clone();
    native_legacy_message_list_with_fetcher(
        state,
        original_action,
        payload,
        session,
        headers,
        MESSAGE_LIST_DEADLINE,
        move |config, password, request, account_email, unchanged_folder_etag| {
            let uid_cache = redis_pool.map(|pool| {
                Arc::new(RedisLegacyMessageListUidCache::new(
                    pool,
                    &account_email,
                    fast_cache_index,
                )) as Arc<dyn fm_imap::LegacyMessageListUidCache>
            });
            async move {
                fetch_legacy_message_list_with_uid_cache_if_changed(
                    config,
                    &password,
                    request,
                    uid_cache,
                    unchanged_folder_etag,
                )
                .await
            }
        },
    )
    .await
}

async fn native_legacy_message_list_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    headers: &HeaderMap,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: FnOnce(
        ImapConnectionConfig,
        String,
        LegacyMessageListRequest,
        String,
        Option<String>,
    ) -> Fut,
    Fut: std::future::Future<Output = fm_core::Result<Option<LegacyMessageList>>>,
{
    let (user, credential_key) = match imap_action_auth(state, original_action, session).await {
        Ok(auth) => auth,
        Err(_) => return legacy_action_error(original_action, AUTH_ERROR, "Not authenticated"),
    };
    let receipt_account_id =
        match resolve_message_body_account_id(payload, session, original_action).await {
            Ok(account_id) => account_id,
            Err(response) => return response,
        };
    let hide_deleted = match legacy_message_list_hide_deleted_setting(
        state,
        original_action,
        user.user_id,
    )
    .await
    {
        Ok(hide_deleted) => hide_deleted,
        Err(_) => {
            return legacy_action_error(
                original_action,
                CANT_GET_MESSAGE_LIST,
                "Cannot read message-list settings",
            )
        }
    };
    let (config, password, account_email) =
        match imap_action_connection_with_email_for_selected_or_payload(
            state,
            original_action,
            payload,
            session,
            user.user_id,
            &credential_key,
        )
        .await
        {
            Ok(connection) => connection,
            Err(_) => {
                return legacy_action_error(
                    original_action,
                    CONNECTION_ERROR,
                    "Cannot connect to the selected mail account",
                )
            }
        };
    let (mut request, raw_cache_hash) =
        match legacy_message_list_raw_key_request_from_payload(payload) {
            Ok(Some(raw_key_request)) => {
                let LegacyMessageListRawKeyRequest {
                    request,
                    cache_hash,
                    account_hash: _account_hash,
                } = raw_key_request;
                (request, Some(cache_hash))
            }
            Ok(None) => match legacy_message_list_request_from_payload(payload) {
                Ok(request) => (request, None),
                Err(message) => {
                    return legacy_action_error(original_action, CANT_GET_MESSAGE_LIST, message)
                }
            },
            Err(message) => {
                return legacy_action_error(original_action, CANT_GET_MESSAGE_LIST, message)
            }
        };
    request.hide_deleted = hide_deleted;
    (request.fast_simple_search, request.permanent_filter) = state
        .config()
        .mail
        .message_list_search_settings(&account_email);
    request.message_list_limit = state.config().mail.message_list_limit(&account_email);
    let cache_account_email = match state.db_pool() {
        Some(pool) => SqlxUserRepository::list_mail_accounts(pool, user.user_id)
            .await
            .ok()
            .and_then(|accounts| accounts.into_iter().next())
            .map(|account| account.email)
            .filter(|email| !email.trim().is_empty())
            .unwrap_or_else(|| account_email.clone()),
        None => account_email.clone(),
    };
    // A durable receipt marker is external to IMAP folder ETags. If this
    // folder has one, do not return a 304 that could resurrect a prior prompt;
    // ordinary RawKey cache validation remains available in other folders.
    let receipt_marker_active = match state.db_pool() {
        Some(pool) => {
            legacy_read_receipt_cache_has_folder(
                pool,
                user.user_id,
                receipt_account_id,
                &request.mailbox,
            )
            .await
        }
        None => Some(false),
    };
    let conditional_cache = matches!(receipt_marker_active, Some(false))
        .then(|| {
            raw_cache_hash.as_deref().and_then(|cache_hash| {
                let folder_etag = legacy_message_list_request_hash_validator(cache_hash)?;
                let cache_state =
                    legacy_message_list_raw_cache_state(cache_hash, &request, &folder_etag)?;
                let response = legacy_message_list_cache_validation_response(
                    headers,
                    &state.config().cache,
                    &cache_state,
                )?;
                Some((folder_etag, response.status()))
            })
        })
        .flatten();
    let unchanged_folder_etag = conditional_cache
        .as_ref()
        .map(|(folder_etag, _)| folder_etag.clone());

    let result = tokio::time::timeout(
        fetch_deadline,
        fetcher(
            config,
            password,
            request.clone(),
            cache_account_email,
            unchanged_folder_etag,
        ),
    )
    .await
    .map_err(|_| FrickmailError::Upstream("Message list fetch timed out".to_string()));

    match result {
        Ok(Ok(Some(mut list))) => {
            if let Some(pool) = state.db_pool() {
                let uids = list
                    .messages
                    .iter()
                    .map(|message| message.uid)
                    .collect::<Vec<_>>();
                if let Ok(Ok(cached)) = tokio::time::timeout(
                    Duration::from_millis(750),
                    fm_user::SqlxUserRepository::read_receipt_cached_uids(
                        pool,
                        user.user_id,
                        receipt_account_id,
                        &legacy_read_receipt_folder_hash(&request.mailbox),
                        &uids,
                        current_epoch() as i64,
                    ),
                )
                .await
                {
                    for message in &mut list.messages {
                        if cached.contains(&message.uid) {
                            message.read_receipt.clear();
                        }
                    }
                }
            }
            let receipt_marker_active = match state.db_pool() {
                Some(pool) => {
                    legacy_read_receipt_cache_has_folder(
                        pool,
                        user.user_id,
                        receipt_account_id,
                        &request.mailbox,
                    )
                    .await
                }
                None => Some(false),
            };
            let raw_cache_state = matches!(receipt_marker_active, Some(false))
                .then(|| {
                    raw_cache_hash.as_deref().and_then(|cache_hash| {
                        legacy_message_list_raw_cache_state(cache_hash, &request, &list.folder.etag)
                    })
                })
                .flatten();
            if let Some(response) = raw_cache_state.as_ref().and_then(|cache_state| {
                legacy_message_list_cache_validation_response(
                    headers,
                    &state.config().cache,
                    cache_state,
                )
            }) {
                return response;
            }

            let mut response = json_value_envelope(
                StatusCode::OK,
                original_action,
                json!({
                    "Result": legacy_message_list_json(&list)
                }),
            );
            if let Some(cache_state) = raw_cache_state {
                legacy_apply_http_cache_headers(
                    response.headers_mut(),
                    &state.config().cache,
                    &cache_state.current_cache_key,
                );
            }
            response
        }
        Ok(Ok(None)) => conditional_cache
            .map(|(_, status)| legacy_empty_response(status))
            .unwrap_or_else(|| {
                legacy_action_error(
                    original_action,
                    CANT_GET_MESSAGE_LIST,
                    "Message-list cache validation failed",
                )
            }),
        Ok(Err(err)) | Err(err) => {
            legacy_action_error(original_action, CANT_GET_MESSAGE_LIST, err.public_message())
        }
    }
}

fn legacy_message_list_request_from_payload(
    payload: &Value,
) -> Result<LegacyMessageListRequest, &'static str> {
    legacy_message_list_request_from_payload_with_limit_default(payload, 10)
}

fn legacy_message_list_raw_key_request_from_payload_values(
    payload: &Value,
) -> Result<LegacyMessageListRequest, &'static str> {
    legacy_message_list_request_from_payload_with_limit_default(payload, 0)
}

fn legacy_message_list_request_from_payload_with_limit_default(
    payload: &Value,
    missing_limit: u32,
) -> Result<LegacyMessageListRequest, &'static str> {
    let mailbox = required_payload_string(payload, "folder", "folder required")?;
    let offset = payload_clamped_u32(payload, "offset");
    let limit = legacy_message_list_payload_limit(payload, missing_limit);
    let prev_uid_next = Some(legacy_message_list_payload_uid_next(payload));
    let use_threads = payload_bool(payload, "useThreads");
    let thread_uid = if use_threads {
        payload_optional_u32(payload, "threadUid").unwrap_or_default()
    } else {
        0
    };
    let thread_algorithm = if use_threads {
        payload_string(payload, "threadAlgorithm").unwrap_or_default()
    } else {
        String::new()
    };

    Ok(LegacyMessageListRequest {
        mailbox,
        offset,
        limit,
        search: payload_string(payload, "search").unwrap_or_default(),
        sort: payload_string(payload, "sort").unwrap_or_default(),
        prev_uid_next,
        hide_deleted: true,
        fast_simple_search: true,
        permanent_filter: String::new(),
        message_list_limit: 10_000,
        use_threads,
        thread_uid,
        thread_algorithm,
    })
}

fn legacy_message_list_payload_limit(payload: &Value, missing_limit: u32) -> u32 {
    if payload.get("limit").is_some() {
        payload_clamped_u32(payload, "limit")
    } else {
        missing_limit
    }
}

fn legacy_message_list_payload_uid_next(payload: &Value) -> u32 {
    payload_optional_u32(payload, "uidNext").unwrap_or_default()
}

#[allow(dead_code)]
fn legacy_message_list_raw_key_from_uri(uri: &Uri) -> Option<String> {
    legacy_action_raw_key_from_uri(uri, "MessageList")
}

fn legacy_action_raw_key_from_uri(uri: &Uri, action: &str) -> Option<String> {
    let query = uri.query()?;
    if !is_legacy_json_request(uri) {
        return None;
    }
    let tail = query.split_once("/0/")?.1.trim_start_matches('/');
    let mut parts = tail.split('/');
    if parts.next()? != action {
        return None;
    }

    while let Some(part) = parts.next() {
        if part == "&q[]=" {
            return parts
                .next()
                .filter(|value| !value.is_empty())
                .map(ToString::to_string);
        }
    }

    None
}

fn legacy_message_list_raw_key_request_from_payload(
    payload: &Value,
) -> Result<Option<LegacyMessageListRawKeyRequest>, &'static str> {
    let Some(raw_key) = payload_optional_string(payload, "RawKey") else {
        return Ok(None);
    };
    let Some(raw_payload) = legacy_raw_key_json(&raw_key) else {
        return Ok(None);
    };
    let Some(values) = raw_payload.as_object() else {
        return Ok(None);
    };
    if values.len() <= 6 {
        return Ok(None);
    }

    let cache_hash = payload_string(&raw_payload, "hash").unwrap_or_default();
    let account_hash = legacy_message_list_raw_key_account_hash(&raw_payload, &cache_hash);

    Ok(Some(LegacyMessageListRawKeyRequest {
        cache_hash,
        account_hash,
        request: legacy_message_list_raw_key_request_from_payload_values(&raw_payload)?,
    }))
}

fn legacy_raw_key_json(raw_key: &str) -> Option<Value> {
    if raw_key.is_empty() {
        return None;
    }
    let decoded = URL_SAFE_NO_PAD
        .decode(raw_key)
        .or_else(|_| URL_SAFE.decode(raw_key))
        .ok()?;
    serde_json::from_slice::<Value>(&decoded).ok()
}

fn legacy_message_list_raw_cache_state(
    request_cache_hash: &str,
    request: &LegacyMessageListRequest,
    current_folder_etag: &str,
) -> Option<LegacyMessageListRawCacheState> {
    if request_cache_hash.is_empty() || current_folder_etag.is_empty() {
        return None;
    }

    let request_hash_validator = legacy_message_list_request_hash_validator(request_cache_hash)?;
    let account_hash =
        legacy_message_list_cache_hash_account(request_cache_hash).unwrap_or_default();
    let params_hash = legacy_message_list_params_hash(request, false, true);
    let current_cache_key = legacy_message_list_cache_key(&params_hash, current_folder_etag);

    Some(LegacyMessageListRawCacheState {
        verify_existing_cache: request_hash_validator == current_folder_etag,
        request_hash_validator,
        account_hash,
        current_cache_key,
    })
}

fn legacy_message_list_request_hash_validator(request_cache_hash: &str) -> Option<String> {
    request_cache_hash
        .split('-')
        .nth(1)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

fn legacy_message_list_raw_key_account_hash(
    raw_payload: &Value,
    request_cache_hash: &str,
) -> String {
    payload_string(raw_payload, "accountHash")
        .or_else(|| legacy_message_list_cache_hash_account(request_cache_hash))
        .unwrap_or_default()
}

fn legacy_message_list_cache_hash_account(request_cache_hash: &str) -> Option<String> {
    request_cache_hash
        .rsplit_once('-')
        .map(|(_, account_hash)| account_hash)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

fn legacy_message_list_cache_validation_response(
    headers: &HeaderMap,
    cache_config: &fm_core::FrickmailCacheConfig,
    cache_state: &LegacyMessageListRawCacheState,
) -> Option<Response> {
    if !cache_state.verify_existing_cache {
        return None;
    }

    legacy_http_cache_validation_response(headers, cache_config, &cache_state.current_cache_key)
}

fn legacy_http_cache_validation_response(
    headers: &HeaderMap,
    cache_config: &fm_core::FrickmailCacheConfig,
    cache_key: &str,
) -> Option<Response> {
    let etag = legacy_http_cache_etag(cache_key, cache_config);
    if legacy_header_contains(headers.get(IF_NONE_MATCH), &etag) {
        return Some(legacy_empty_response(StatusCode::NOT_MODIFIED));
    }
    if headers
        .get(IF_MATCH)
        .is_some_and(|value| !legacy_header_value_contains(value, &etag))
    {
        return Some(legacy_empty_response(StatusCode::PRECONDITION_FAILED));
    }

    None
}

fn legacy_apply_http_cache_headers(
    headers: &mut HeaderMap,
    cache_config: &fm_core::FrickmailCacheConfig,
    cache_key: &str,
) {
    headers.insert(
        CACHE_CONTROL,
        HeaderValue::from_static("private, no-cache, must-revalidate, max-age=0"),
    );

    let etag = format!("\"{}\"", legacy_http_cache_etag(cache_key, cache_config));
    if let Ok(etag) = HeaderValue::from_str(&etag) {
        headers.insert(ETAG, etag);
    }

    if cache_config.http_expires > 0 {
        let expires = (Utc::now() + ChronoDuration::seconds(cache_config.http_expires))
            .format("%a, %-d %b %Y %H:%M:%S UTC")
            .to_string();
        if let Ok(expires) = HeaderValue::from_str(&expires) {
            headers.insert(EXPIRES, expires);
        }
    }
}

fn legacy_http_cache_etag(cache_key: &str, cache_config: &fm_core::FrickmailCacheConfig) -> String {
    let mut digest = Md5::new();
    digest.update(cache_key.as_bytes());
    digest.update(cache_config.index.as_bytes());
    digest.update(LEGACY_SNAPPYMAIL_APP_VERSION.as_bytes());
    format!("{:x}", digest.finalize())
}

fn legacy_header_contains(value: Option<&HeaderValue>, needle: &str) -> bool {
    value.is_some_and(|value| legacy_header_value_contains(value, needle))
}

fn legacy_header_value_contains(value: &HeaderValue, needle: &str) -> bool {
    value
        .to_str()
        .is_ok_and(|header| !needle.is_empty() && header.contains(needle))
}

fn legacy_empty_response(status: StatusCode) -> Response {
    Response::builder()
        .status(status)
        .body(Body::empty())
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

async fn legacy_message_list_hide_deleted_setting(
    state: &AppState,
    original_action: &str,
    user_id: i64,
) -> Result<bool, Response> {
    let Some(pool) = state.db_pool() else {
        return Ok(true);
    };

    match SqlxUserRepository::find_by_id(pool, user_id).await {
        Ok(Some(user)) => Ok(legacy_message_list_hide_deleted_from_settings(
            &user.settings,
        )),
        Ok(None) => Err(json_result_error(original_action, "Not authenticated")),
        Err(err) => Err(json_result_error(original_action, &err.public_message())),
    }
}

fn legacy_message_list_hide_deleted_from_settings(settings: &Value) -> bool {
    settings
        .get("HideDeleted")
        .or_else(|| settings.get("hideDeleted"))
        .map(legacy_php_truthy)
        .unwrap_or(true)
}

fn legacy_php_truthy(value: &Value) -> bool {
    match value {
        Value::Bool(value) => *value,
        Value::Null => false,
        Value::Number(number) => number
            .as_i64()
            .map(|value| value != 0)
            .or_else(|| number.as_u64().map(|value| value != 0))
            .or_else(|| number.as_f64().map(|value| value != 0.0))
            .unwrap_or(false),
        Value::String(value) => !value.is_empty() && value != "0",
        Value::Array(values) => !values.is_empty(),
        Value::Object(values) => !values.is_empty(),
    }
}

async fn native_legacy_folders(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    native_legacy_folders_with_fetcher(
        state,
        original_action,
        payload,
        session,
        |config, password, discover_subscriptions| async move {
            fetch_legacy_folders(config, &password, discover_subscriptions).await
        },
    )
    .await
}

async fn native_legacy_folders_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    fetcher: F,
) -> Response
where
    F: FnOnce(ImapConnectionConfig, String, bool) -> Fut,
    Fut: std::future::Future<Output = fm_core::Result<LegacyFolderCollection>>,
{
    let (user, credential_key) = match imap_action_auth(state, original_action, session).await {
        Ok(auth) => auth,
        Err(response) => return response,
    };
    let account_id = match resolve_message_body_account_id(payload, session, original_action).await
    {
        Ok(account_id) => account_id,
        Err(response) => return response,
    };
    let Some(pool) = state.db_pool() else {
        return json_result_error(original_action, "Frickmail database is not configured");
    };
    let settings =
        match SqlxUserRepository::get_mail_account_settings(pool, user.user_id, account_id).await {
            Ok(Some(settings)) => settings,
            Ok(None) => return json_result_error(original_action, "Account not found"),
            Err(error) => return json_result_error(original_action, &error.public_message()),
        };
    let discover_subscriptions = settings
        .get("HideUnsubscribed")
        .or_else(|| settings.get("hideUnsubscribed"))
        .is_some_and(legacy_php_truthy);
    let checkable = legacy_checkable_folders(&settings);
    let (config, password) = match imap_action_connection_for_selected_or_payload(
        state,
        original_action,
        payload,
        session,
        user.user_id,
        &credential_key,
    )
    .await
    {
        Ok(connection) => connection,
        Err(response) => return response,
    };

    match fetcher(config, password, discover_subscriptions).await {
        Ok(collection) => json_value_envelope(
            StatusCode::OK,
            original_action,
            json!({
                "Result": legacy_folder_collection_json(&collection, &checkable)
            }),
        ),
        Err(error) => json_result_error(original_action, &error.public_message()),
    }
}

fn legacy_checkable_folders(settings: &Value) -> HashSet<String> {
    let Some(setting) = settings
        .get("CheckableFolder")
        .or_else(|| settings.get("checkableFolder"))
    else {
        return HashSet::new();
    };
    let values = match setting {
        Value::String(encoded) => serde_json::from_str::<Vec<String>>(encoded).unwrap_or_default(),
        Value::Array(values) => values
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect(),
        _ => Vec::new(),
    };
    values.into_iter().collect()
}

async fn native_legacy_folder_information(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let fetch_new_messages = state.config().mail.fetch_new_messages;
    native_legacy_folder_information_with_fetcher(
        state,
        original_action,
        payload,
        session,
        FOLDER_INFORMATION_DEADLINE,
        |config, password, folder, prev_uid_next, flag_uids| async move {
            fetch_legacy_folder_information(
                config,
                &password,
                &folder,
                prev_uid_next,
                flag_uids,
                fetch_new_messages,
            )
            .await
        },
    )
    .await
}

async fn native_legacy_folder_information_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: FnOnce(ImapConnectionConfig, String, String, Option<u32>, Option<Vec<u32>>) -> Fut,
    Fut: std::future::Future<Output = fm_core::Result<LegacyFolderInformation>>,
{
    let (config, password) =
        match legacy_imap_connection_context(state, original_action, payload, session).await {
            Ok(connection) => connection,
            Err(response) => return response,
        };
    let folder = match required_payload_string(payload, "folder", "folder required") {
        Ok(folder) => folder,
        Err(message) => return json_result_error(original_action, message),
    };
    let prev_uid_next = payload_optional_i64(payload, "uidNext").map(|value| value as u32);
    let flag_uids = payload_uid_list_optional(payload, "flagsUids");

    let result = tokio::time::timeout(
        fetch_deadline,
        fetcher(config, password, folder, prev_uid_next, flag_uids),
    )
    .await
    .map_err(|_| FrickmailError::Upstream("Folder information fetch timed out".to_string()));

    match result {
        Ok(Ok(info)) => json_value_envelope(
            StatusCode::OK,
            original_action,
            json!({
                "Result": legacy_folder_information_json(&info)
            }),
        ),
        Ok(Err(err)) | Err(err) => json_result_error(original_action, &err.public_message()),
    }
}

async fn native_legacy_folder_information_multiply(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
) -> Response {
    let fetch_new_messages = state.config().mail.fetch_new_messages;
    native_legacy_folder_information_multiply_with_fetcher(
        state,
        original_action,
        payload,
        session,
        FOLDER_INFORMATION_DEADLINE,
        |config, password, folder| async move {
            fetch_legacy_folder_information(
                config,
                &password,
                &folder,
                None,
                None,
                fetch_new_messages,
            )
            .await
        },
    )
    .await
}

async fn native_legacy_folder_information_multiply_with_fetcher<F, Fut>(
    state: &AppState,
    original_action: &str,
    payload: &Value,
    session: &fm_session::Session,
    fetch_deadline: Duration,
    fetcher: F,
) -> Response
where
    F: Fn(ImapConnectionConfig, String, String) -> Fut + Clone,
    Fut: std::future::Future<Output = fm_core::Result<LegacyFolderInformation>>,
{
    let (config, password) =
        match legacy_imap_connection_context(state, original_action, payload, session).await {
            Ok(connection) => connection,
            Err(response) => return response,
        };
    let folders = payload_array(payload, "folders")
        .into_iter()
        .filter_map(|value| match value {
            Value::String(folder) if !folder.trim().is_empty() => Some(folder),
            Value::Number(number) => Some(number.to_string()),
            _ => None,
        })
        .collect::<Vec<_>>();

    let mut results = Vec::new();
    for folder in folders {
        let fetch = fetcher.clone();
        let result = tokio::time::timeout(
            fetch_deadline,
            fetch(config.clone(), password.clone(), folder),
        )
        .await
        .map_err(|_| FrickmailError::Upstream("Folder information fetch timed out".to_string()));
        if let Ok(Ok(info)) = result {
            results.push(legacy_folder_information_json(&info));
        }
    }

    json_value_envelope(
        StatusCode::OK,
        original_action,
        json!({
            "Result": results
        }),
    )
}

