    #[tokio::test]
    async fn native_admin_backup_creates_bounded_legacy_archive() {
        let root = std::env::temp_dir().join(format!(
            "frickmail-backup-test-{}",
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let private = root.join("private");
        tokio::fs::create_dir_all(private.join("configs"))
            .await
            .unwrap();
        tokio::fs::write(private.join("configs/application.ini"), b"test")
            .await
            .unwrap();
        tokio::fs::create_dir_all(private.join("cache"))
            .await
            .unwrap();
        tokio::fs::write(private.join("cache/skip"), b"skip")
            .await
            .unwrap();

        let token_hash = fm_user::hash_admin_token("backup-secret").unwrap();
        let state = AppState::new(admin_backup_config(
            Some(private.to_string_lossy().into_owned()),
            Some(token_hash),
        ));
        let mut headers = axum::http::HeaderMap::new();
        headers.insert("x-frickmail-admin-token", "wrong".parse().unwrap());
        let response =
            super::native_admin_backup_data(&state, "JsonAdminBackupData", &headers).await;
        assert_eq!(read_json(response).await["Result"], false);

        let mut headers = axum::http::HeaderMap::new();
        headers.insert("x-frickmail-admin-token", "backup-secret".parse().unwrap());
        let response =
            super::native_admin_backup_data(&state, "JsonAdminBackupData", &headers).await;
        let result = read_json(response).await["Result"].clone();
        let data = result["data"].as_str().unwrap();
        let encoded = data.strip_prefix("data:application/zip;base64,").unwrap();
        let bytes = STANDARD.decode(encoded).unwrap();
        let cursor = std::io::Cursor::new(bytes);
        let mut archive = zip::ZipArchive::new(cursor).unwrap();
        assert_eq!(archive.len(), 2);
        assert!(archive.by_name("configs/").is_ok());
        use std::io::Read;
        let mut file = archive.by_name("configs/application.ini").unwrap();
        let mut contents = String::new();
        file.read_to_string(&mut contents).unwrap();
        assert_eq!(contents, "test");
        assert!(result["name"].as_str().unwrap().ends_with(".zip"));
    }

    #[tokio::test]
    async fn native_admin_restore_extracts_safely_within_private_data() {
        let root = std::env::temp_dir().join(format!(
            "frickmail-restore-test-{}",
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let private = root.join("private");
        tokio::fs::create_dir_all(&private).await.unwrap();
        let archive_path = root.join("backup.zip");
        {
            let file = std::fs::File::create(&archive_path).unwrap();
            let mut zip = zip::ZipWriter::new(file);
            let options = zip::write::SimpleFileOptions::default();
            zip.start_file("domains/example.com", options).unwrap();
            std::io::Write::write_all(&mut zip, b"domain").unwrap();
            zip.finish().unwrap();
        }
        let archive = std::fs::read(&archive_path).unwrap();
        let token_hash = fm_user::hash_admin_token("backup-secret").unwrap();
        let state = AppState::with_db_pool(
            admin_backup_config(
                Some(private.to_string_lossy().into_owned()),
                Some(token_hash),
            ),
            None,
        );
        let (headers, body) = backup_multipart_body(&archive).await;
        let response =
            super::native_admin_restore_data(&state, "JsonAdminRestoreData", &headers, &body).await;
        assert_eq!(read_json(response).await["Result"], true);
        assert_eq!(
            std::fs::read(private.join("domains/example.com")).unwrap(),
            b"domain"
        );
    }

    #[tokio::test]
    async fn native_change_password_rejects_malformed_kdf_salt_without_rotation() {
        let user_id = 1725;
        let (pool, state, session, _) =
            change_password_test_state(user_id, "change-bad-salt", "correct-horse", true).await;
        sqlx::query("UPDATE frickmail_users SET kdf_salt = ? WHERE id = ?")
            .bind(vec![1_u8, 2, 3])
            .bind(user_id)
            .execute(&pool)
            .await
            .unwrap();

        let response = super::native_change_password(
            &state,
            "ChangePassword",
            &json!({
                "PrevPassword": "correct-horse",
                "NewPassword": "new-strong-passphrase"
            }),
            &session,
        )
        .await;
        let body = read_json(response).await;
        assert_eq!(body["Result"]["ok"], false);
        assert!(body["Result"]["error"]
            .as_str()
            .unwrap()
            .contains("invalid Frickmail KDF salt length"));

        let user = SqlxUserRepository::find_by_id(&pool, user_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(user.kdf_salt, vec![1_u8, 2, 3]);
        let old_key =
            fm_user::derive_credential_key("correct-horse", &[7_u8; fm_user::KDF_SALT_BYTES])
                .unwrap();
        let secret =
            SqlxUserRepository::get_mail_account_connection_secret(&pool, user_id, user_id * 10)
                .await
                .unwrap()
                .unwrap();
        assert_eq!(
            fm_user::decrypt_account_secret(&secret.encrypted_password.unwrap(), &old_key)
                .unwrap()
                .as_deref(),
            Some("imap-secret")
        );
    }

    #[tokio::test]
    async fn native_change_password_rotates_user_and_account_secrets_atomically() {
        let user_id = 1720;
        let account_id = user_id * 10;
        let (pool, state, session, old_key) =
            change_password_test_state(user_id, "change-success", "correct-horse", true).await;
        let response = super::native_change_password(
            &state,
            "ChangePassword",
            &json!({
                "PrevPassword": "correct-horse",
                "NewPassword": "new-strong-passphrase"
            }),
            &session,
        )
        .await;
        let body = read_json(response).await;
        assert_eq!(body["Result"], true);

        let user = SqlxUserRepository::find_by_id(&pool, user_id)
            .await
            .unwrap()
            .unwrap();
        assert!(fm_user::verify_password("new-strong-passphrase", &user.password_hash).unwrap());
        assert_ne!(user.kdf_salt, [7_u8; fm_user::KDF_SALT_BYTES]);
        let new_key =
            fm_user::derive_credential_key("new-strong-passphrase", &user.kdf_salt).unwrap();
        assert_ne!(old_key, new_key);
        let secret =
            SqlxUserRepository::get_mail_account_connection_secret(&pool, user_id, account_id)
                .await
                .unwrap()
                .unwrap();
        let encrypted_password = secret.encrypted_password.unwrap();
        assert_eq!(
            fm_user::decrypt_account_secret(&encrypted_password, &new_key)
                .unwrap()
                .as_deref(),
            Some("imap-secret")
        );
        assert!(
            fm_user::decrypt_account_secret(&encrypted_password, &old_key)
                .unwrap()
                .is_none()
        );
        assert!(session
            .get::<String>(CREDENTIAL_KEY_SESSION_KEY)
            .await
            .unwrap()
            .is_none());
    }

