    #[test]
    fn legacy_compose_cid_linking_is_linear_for_periodic_input() {
        let periodic = "a".repeat(super::COMPOSE_ATTACHMENT_CONTENT_ID_LIMIT_BYTES - 1);
        let occurrence = format!("<img src=\"cid:{periodic}x\">");
        let html = occurrence.repeat(
            super::COMPOSE_HTML_RAW_LIMIT_BYTES
                .checked_div(occurrence.len())
                .unwrap_or_default(),
        );
        let mut attachments = (0..super::COMPOSE_ATTACHMENT_LIMIT)
            .map(|index| super::LegacyComposeAttachment {
                spec: super::LegacyComposeAttachmentSpec {
                    token: format!("{index:040x}"),
                    file_name: format!("part-{index}.bin"),
                    is_inline: true,
                    content_id: format!("{periodic}y"),
                    content_location: String::new(),
                    mime_type: "application/octet-stream".to_string(),
                    is_linked: false,
                },
                data: Vec::new(),
            })
            .collect::<Vec<_>>();

        let started = std::time::Instant::now();
        super::legacy_mark_linked_compose_attachments(&mut attachments, &html);

        assert!(attachments
            .iter()
            .all(|attachment| !attachment.spec.is_linked));
        assert!(
            started.elapsed() < std::time::Duration::from_secs(2),
            "CID extraction should make one bounded pass over the HTML"
        );
    }

    #[test]
    fn legacy_compose_rfc822_attachment_preserves_raw_bytes_with_eight_bit_cte() {
        let payload = json!({
            "from": "sender@example.com",
            "to": "recipient@example.com",
            "plain": "Forwarded message"
        });
        let mut request =
            super::legacy_send_message_request_from_payload(&payload, "sender@example.com")
                .unwrap();
        let eml = format!("Subject: café\r\n\r\n{}\r\n", "x".repeat(120));
        request.attachments = vec![super::LegacyComposeAttachment {
            spec: super::LegacyComposeAttachmentSpec {
                token: "d".repeat(40),
                file_name: "forwarded.eml".to_string(),
                is_inline: false,
                content_id: String::new(),
                content_location: String::new(),
                mime_type: "message/rfc822".to_string(),
                is_linked: false,
            },
            data: eml.as_bytes().to_vec(),
        }];

        let raw = super::build_legacy_send_message(&request, false)
            .unwrap()
            .formatted();
        let raw = String::from_utf8(raw).unwrap();
        assert!(raw.contains("Content-Type: message/rfc822"));
        assert!(raw.contains("Content-Transfer-Encoding: 8bit"));
        assert!(raw.contains(&eml));
        assert!(!raw.contains("Content-Transfer-Encoding: quoted-printable"));
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn legacy_mime_build_keeps_the_async_runtime_responsive() {
        let started = Instant::now();
        let heartbeat = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(20)).await;
            started.elapsed()
        });
        let build = super::legacy_run_mime_build(|| {
            std::thread::sleep(Duration::from_millis(150));
            Ok(())
        });
        let (build, heartbeat) = tokio::join!(build, heartbeat);

        build.unwrap();
        assert!(heartbeat.unwrap() < Duration::from_millis(100));
    }

    #[test]
    fn legacy_compose_attachment_metadata_rejects_capability_escape_and_header_injection() {
        for payload in [
            json!({"attachments": {"../outside": {"name": "report.pdf"}}}),
            json!({"attachments": {("a".repeat(40)): {"name": "report.pdf\r\nBcc: victim@example.com"}}}),
            json!({"attachments": {("a".repeat(40)): {"name": "report.pdf", "cId": "ok\r\nX-Evil: yes"}}}),
            json!({"attachments": []}),
        ] {
            assert!(
                super::legacy_validate_compose_limits(&payload).is_err(),
                "payload unexpectedly passed: {payload}"
            );
        }
    }

    #[test]
    fn legacy_message_json_keeps_nonempty_optional_body_fields() {
        let from = vec!["Sender <sender@example.com>".to_string()];
        let reply_to = vec!["reply@example.com".to_string()];
        let to = vec!["Recipient <recipient@example.com>".to_string()];
        let cc = vec!["cc@example.com".to_string()];
        let bcc = vec!["hidden@example.com".to_string()];
        let sender = vec!["Actual <actual@example.com>".to_string()];
        let delivered_to = vec!["delivered@example.com".to_string()];
        let message = super::legacy_message_json(
            "INBOX",
            54,
            "hash",
            "Optional fields",
            false,
            0,
            "",
            false,
            &Default::default(),
            None,
            "<p>Hello</p>",
            "",
            "",
            "",
            "<root@example>",
            "receipt@example.com",
            0,
            "internal",
            Value::Null,
            None,
            Some(from.as_slice()),
            Some(reply_to.as_slice()),
            Some(to.as_slice()),
            Some(cc.as_slice()),
            Some(bcc.as_slice()),
            Some(sender.as_slice()),
            Some(delivered_to.as_slice()),
            &Default::default(),
            0,
            &[],
            Some("gmail-message-id"),
            None,
            &[],
            &[],
        );

        assert_eq!(message["references"], "<root@example>");
        assert_eq!(message["readReceipt"], "receipt@example.com");
        assert_eq!(message["html"], "<p>Hello</p>");
        assert_eq!(message["plain"], "");
        assert_eq!(message["preview"], Value::Null);
        assert_eq!(message["id"], "gmail-message-id");
        assert_eq!(message["from"][0]["name"], "Sender");
        assert_eq!(message["from"][0]["email"], "sender@example.com");
        assert_eq!(message["replyTo"][0]["email"], "reply@example.com");
        assert_eq!(message["to"][0]["name"], "Recipient");
        assert_eq!(message["to"][0]["email"], "recipient@example.com");
        assert_eq!(message["cc"][0]["email"], "cc@example.com");
        assert_eq!(message["bcc"][0]["email"], "hidden@example.com");
        assert_eq!(message["sender"][0]["name"], "Actual");
        assert_eq!(message["sender"][0]["email"], "actual@example.com");
        assert_eq!(message["deliveredTo"][0]["email"], "delivered@example.com");
        assert_eq!(message["attachments"], Value::Null);
        assert_eq!(message["headers"], Value::Null);
        assert_eq!(message["dateTimestamp"], 0);
        assert_eq!(message["dateTimestampSource"], "internal");
        assert!(message.get("date").is_none());
        assert!(message.get("threads").is_none());
        assert!(message.get("threadUnseen").is_none());
    }

