    #[test]
    fn legacy_apply_message_crypto_json_matches_mailso_keys() {
        let mut value = json!({});
        let crypto = fm_imap::LegacyMessageCrypto {
            pgp_signed: Some(fm_imap::LegacyPgpSigned {
                part_id: "1".to_string(),
                sig_part_id: Some("2".to_string()),
                mic_alg: Some("pgp-sha256".to_string()),
            }),
            pgp_encrypted: Some(fm_imap::LegacyPgpEncrypted {
                part_id: "2".to_string(),
                key_ids: None,
            }),
            smime_signed: Some(fm_imap::LegacySmimeSigned {
                part_id: "TEXT".to_string(),
                sig_part_id: Some("2".to_string()),
                mic_alg: "sha-256".to_string(),
                detached: true,
            }),
            smime_encrypted: Some(fm_imap::LegacyPartId {
                part_id: "1".to_string(),
            }),
        };

        super::legacy_apply_message_crypto_json(&mut value, &crypto);

        assert_eq!(value["pgpSigned"]["partId"], "1");
        assert_eq!(value["pgpSigned"]["sigPartId"], "2");
        assert_eq!(value["pgpSigned"]["micAlg"], "pgp-sha256");
        assert_eq!(value["pgpEncrypted"]["partId"], "2");
        assert!(value["pgpEncrypted"].get("keyIds").is_none());
        assert_eq!(value["smimeSigned"]["partId"], "TEXT");
        assert_eq!(value["smimeSigned"]["sigPartId"], "2");
        assert_eq!(value["smimeSigned"]["micAlg"], "sha-256");
        assert_eq!(value["smimeSigned"]["detached"], true);
        assert_eq!(value["smimeEncrypted"]["partId"], "1");

        let mut armored = json!({});
        super::legacy_apply_message_crypto_json(
            &mut armored,
            &fm_imap::LegacyMessageCrypto {
                pgp_signed: Some(fm_imap::LegacyPgpSigned {
                    part_id: "3.2".to_string(),
                    sig_part_id: None,
                    mic_alg: None,
                }),
                pgp_encrypted: Some(fm_imap::LegacyPgpEncrypted {
                    part_id: "3.2".to_string(),
                    key_ids: Some(vec!["0123456789ABCDEF".to_string()]),
                }),
                ..Default::default()
            },
        );
        assert_eq!(armored["pgpSigned"], json!({"partId": "3.2"}));
        assert_eq!(
            armored["pgpEncrypted"],
            json!({"partId": "3.2", "keyIds": ["0123456789ABCDEF"]})
        );
    }

    #[tokio::test]
    async fn native_legacy_message_decodes_legacy_raw_key_get_shape() {
        let key = [49_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let (state, session) = message_body_test_state(1816, 1817, &key).await;
        let raw_key = URL_SAFE_NO_PAD.encode(json!(["INBOX", "52", 1, "account"]).to_string());
        let captured = Arc::new(Mutex::new(None));
        let captured_for_fetch = Arc::clone(&captured);

        let response = super::native_legacy_message_with_fetcher(
            &state,
            "Message",
            &json!({"account_id": 1817, "RawKey": raw_key}),
            &session,
            &HeaderMap::new(),
            Duration::from_secs(1),
            move |_config, _password, folder, uid| {
                let captured = Arc::clone(&captured_for_fetch);
                async move {
                    *captured.lock().unwrap() = Some((folder, uid));
                    Ok(Some(vec![BodyPreviewPart {
                        kind: BodyPartKind::RawMessage,
                        raw: b"Subject: RawKey body\r\n\r\nHello from raw key".to_vec(),
                        is_complete: true,
                        flags: Vec::new(),
                        crypto: Default::default(),
                        metadata: Default::default(),
                    }]))
                }
            },
        )
        .await;
        let body = read_json(response).await;

        assert_eq!(body["Action"], "Message");
        assert_eq!(body["Result"]["folder"], "INBOX");
        assert_eq!(body["Result"]["uid"], 52);
        assert_eq!(body["Result"]["subject"], "RawKey body");
        assert_eq!(body["Result"]["plain"], "Hello from raw key");
        assert_eq!(
            captured.lock().unwrap().clone().unwrap(),
            ("INBOX".to_string(), 52)
        );

        let parsed = super::legacy_message_request_from_payload(&json!({
            "RawKey": URL_SAFE_NO_PAD.encode(json!(["Archive", 53, 0, "account-2"]).to_string())
        }))
        .unwrap();
        assert_eq!(parsed.folder, "Archive");
        assert_eq!(parsed.uid, 53);
        assert!(!parsed.use_threads);
        assert_eq!(parsed.account_hash, "account-2");
    }

    #[tokio::test]
    async fn native_legacy_message_raw_key_cache_applies_headers_and_flags() {
        let key = [62_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let (state, session) = message_body_test_state(1934, 1935, &key).await;
        let flags = vec!["\\seen".to_string(), "$label1".to_string()];
        let raw_key = URL_SAFE_NO_PAD.encode(json!(["INBOX", 52, 0, "account"]).to_string());
        let expected_etag =
            legacy_message_raw_key_cache_etag(&state.config().cache, flags.as_slice());
        let expected_header = format!("\"{expected_etag}\"");

        let response = super::native_legacy_message_with_fetcher(
            &state,
            "Message",
            &json!({"account_id": 1935, "RawKey": raw_key}),
            &session,
            &HeaderMap::new(),
            Duration::from_secs(1),
            {
                let flags = flags.clone();
                move |_config, _password, _folder, _uid| async move {
                    Ok(Some(vec![BodyPreviewPart {
                        kind: BodyPartKind::RawMessage,
                        raw: b"Subject: Cacheable\r\n\r\nBody".to_vec(),
                        is_complete: true,
                        flags,
                        crypto: Default::default(),
                        metadata: Default::default(),
                    }]))
                }
            },
        )
        .await;

        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(CACHE_CONTROL)
                .and_then(|v| v.to_str().ok()),
            Some("private, no-cache, must-revalidate, max-age=0")
        );
        assert_eq!(
            response.headers().get(ETAG).and_then(|v| v.to_str().ok()),
            Some(expected_header.as_str())
        );
        assert!(response.headers().get(EXPIRES).is_some());

        let body = read_json(response).await;
        assert_eq!(body["Result"]["flags"][0], "\\seen");
        assert_eq!(body["Result"]["flags"][1], "$label1");
    }

