    #[tokio::test]
    async fn gnupg_export_and_decrypt_use_private_key_passphrase() {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let temp_root = std::env::temp_dir().join(format!("frickmail-gnupg-test-{unique}"));
        std::fs::create_dir_all(&temp_root).unwrap();
        let pool = user_db_pool().await;
        create_mail_account_tables(&pool).await;
        seed_user(&pool, 9200, "gnupg-passphrase", None).await;
        sqlx::query(
            "INSERT INTO frickmail_mail_accounts
                (id, user_id, label, email, type, imap_host, imap_port, imap_secure,
                 smtp_host, smtp_port, smtp_secure, login, encrypted_password,
                 encrypted_oauth_refresh_token, oauth_tenant, is_primary, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)",
        )
        .bind(910_i64)
        .bind(9200_i64)
        .bind("Primary")
        .bind("primary@example.com")
        .bind("imap")
        .bind("imap.example.com")
        .bind(993_i64)
        .bind("SSL")
        .bind("smtp.example.com")
        .bind(465_i64)
        .bind("SSL")
        .bind("primary@example.com")
        .bind(fm_user::encrypt_account_secret("imap-password", &[7_u8; CREDENTIAL_KEY_BYTES]).unwrap())
        .bind(None::<Vec<u8>>)
        .bind(None::<String>)
        .bind(true)
        .execute(&pool)
        .await
        .unwrap();
        let mut config = test_config(None);
        config.tmp_dir = temp_root.to_string_lossy().to_string();
        let state = AppState::with_db_pool(config, Some(pool.clone()));
        let session = authenticated_session(9200, "gnupg-passphrase", None).await;
        session
            .insert(
                fm_session::CREDENTIAL_KEY_SESSION_KEY,
                STANDARD.encode([7_u8; CREDENTIAL_KEY_BYTES]),
            )
            .await
            .unwrap();
        session
            .insert(
                fm_session::SELECTED_ACCOUNT_SESSION_KEY,
                fm_core::SelectedMailAccountSession { account_id: 910 },
            )
            .await
            .unwrap();
        let passphrase = "correct horse battery staple";

        let response = super::native_gnupg_generate_key(
            &state,
            "GnupgGenerateKey",
            &json!({
                "email": "gnupg-passphrase@example.com",
                "passphrase": passphrase
            }),
            &session,
        )
        .await;
        let body = read_json(response).await;
        let fingerprint = body["Result"].as_str().unwrap();
        assert_eq!(fingerprint.len(), 40);

        let response = super::native_gnupg_export_key(
            &state,
            "GnupgExportKey",
            &json!({"keyId": fingerprint, "isPrivate": true, "passphrase": passphrase}),
            &session,
        )
        .await;
        let exported = read_json(response).await;
        let exported = exported["Result"].as_str().unwrap().to_string();
        assert!(exported.contains("-----BEGIN PGP PRIVATE KEY BLOCK-----"));

        let encrypted = super::run_gnupg(
            &state,
            9200,
            &[
                "--armor",
                "--local-user",
                fingerprint,
                "--recipient",
                fingerprint,
                "--sign",
                "--encrypt",
            ],
            Some(b"secret parity payload".to_vec()),
            Some((fingerprint.to_string(), passphrase.to_string())),
        )
        .await
        .unwrap();

        let response = super::native_gnupg_decrypt(
            &state,
            "GnupgDecrypt",
            &json!({
                "data": String::from_utf8(encrypted.output).unwrap(),
                "keyId": fingerprint,
                "passphrase": passphrase
            }),
            &session,
        )
        .await;
        let body = read_json(response).await;
        let decrypted = body["Result"]["data"].as_str().unwrap();
        assert_eq!(decrypted.trim_end_matches('\n'), "secret parity payload");
        assert_eq!(body["Result"]["signatures"].as_array().unwrap().len(), 1);
        assert_eq!(body["Result"]["signatures"][0]["status"], 0);
        assert_eq!(body["Result"]["signatures"][0]["summary"], 0);
        assert_eq!(body["Result"]["signatures"][0]["valid"], 0);
        let _ = std::fs::remove_dir_all(&temp_root);
    }

    #[test]
    fn verification_parser_matches_legacy_php_fields() {
        let signatures = super::parse_verification_signature(&[
            "NEWSIG".to_string(),
            "GOODSIG ABCDEF0123456789 Alice%20Example%20%3Calice@example.com%3E".to_string(),
            "VALIDSIG FINGERPRINT 2026-08-25 1787640000 0 4 0 1 8 00 PRIMARY".to_string(),
        ]);
        assert_eq!(signatures.len(), 1);
        assert_eq!(signatures[0]["status"], 0);
        assert_eq!(signatures[0]["summary"], 0);
        assert_eq!(signatures[0]["keyid"], "ABCDEF0123456789");
        assert_eq!(signatures[0]["uid"], "Alice Example <alice@example.com>");
        assert_eq!(signatures[0]["fingerprint"], "FINGERPRINT");
        assert_eq!(signatures[0]["timestamp"], 1_787_640_000);
        assert_eq!(signatures[0]["expires"], 0);
        assert_eq!(signatures[0]["version"], 4);
        assert_eq!(signatures[0]["valid"], 0);

        let result = super::legacy_verification_result(&signatures);
        assert_eq!(result["message"], "The signature is fully valid.");
    }

    #[test]
    fn clearsigned_verification_body_matches_php_decoding() {
        let base64_mime = b"Content-Transfer-Encoding: Base64\r\n";
        assert_eq!(
            super::decode_legacy_verified_body(base64_mime, b"aGVsbG8=").unwrap(),
            b"hello".to_vec()
        );

        let quoted = super::decode_legacy_verified_body(
            b"Content-Transfer-Encoding: quoted-printable\r\n",
            b"hello=\r\nworld=A",
        )
        .unwrap_err();
        assert_eq!(quoted, "Invalid quoted-printable message part");

        assert_eq!(
            super::decode_quoted_printable_verified_body(b"hello=\r\nwor=3Dld").unwrap(),
            b"hello\r\nwor=ld".to_vec()
        );
    }

    #[test]
    fn verification_parser_preserves_bad_and_multiple_signatures() {
        let signatures = super::parse_verification_signature(&[
            "BADSIG FEDCBA9876543210 Bob%20Example".to_string(),
            "ERRSIG ABCDEF0123456789 1 10 00 1787640000 9".to_string(),
        ]);
        assert_eq!(signatures.len(), 2);
        assert!(signatures.iter().all(|signature| signature["status"] == 1));
        assert!(signatures.iter().all(|signature| signature["summary"] == 4));
        assert!(signatures
            .iter()
            .all(|signature| signature["valid"] == false));

        let result = super::legacy_verification_result(&signatures);
        assert_eq!(
            result["message"],
            "The signature is bad. It might be useful to check other bits and display more information, i.e. a revoked certificate might not render a signature invalid when the message was received prior to the cause for the revocation."
        );

        let missing =
            super::parse_verification_signature(&["ENC_TO ABCDEF0123456789 1 0".to_string()]);
        assert!(missing.is_empty());
        assert_eq!(super::legacy_verification_result(&missing), json!(false));
    }

