    #[tokio::test]
    async fn client_pgp_with_staged_attachment_rejects_before_send_or_save_side_effects() {
        let key = [64_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let temp_root = std::env::temp_dir().join(format!(
            "frickmail-client-pgp-attachment-{}",
            super::legacy_random_compose_attachment_token()
        ));
        let mut config = test_config(None);
        config.tmp_dir = temp_root.to_string_lossy().to_string();
        let (state, session) =
            message_body_test_state_with_config(8_942, 8_943, &key, config).await;
        let scope =
            super::LegacyComposeStagingScope::new(&temp_root.to_string_lossy(), 8_942, 8_943);
        let token = "d".repeat(40);
        super::legacy_stage_compose_attachment(&scope, &token, b"MUST-REMAIN-STAGED", false)
            .await
            .unwrap();
        let payload = json!({
            "account_id": 8_943,
            "from": "work@example.com",
            "to": "recipient@example.net",
            "saveFolder": "Drafts",
            "boundary": "client-pgp-boundary",
            "signed": "Content-Type: ignored\r\n\r\n--client-pgp-boundary--\r\n",
            "attachments": {
                (token.clone()): {"name": "must-remain.txt", "inline": false, "type": "text/plain"}
            }
        });
        let sent = Arc::new(Mutex::new(None));
        let sender = RecordingSmtpSender {
            succeed: true,
            message: Arc::clone(&sent),
        };
        let send_response = super::native_send_message_inner_with_sender(
            &state,
            "SendMessage",
            &payload,
            &session,
            Arc::new(std::sync::atomic::AtomicU8::new(super::SEND_PHASE_PRE_SMTP)),
            &sender,
        )
        .await;
        let send_body = read_json(send_response).await;
        assert!(send_body["Result"]["error"]
            .as_str()
            .unwrap()
            .contains("Client-provided OpenPGP MIME"));
        assert!(sent.lock().unwrap().is_none());
        assert!(scope.path(&token).unwrap().exists());

        let appended = Arc::new(Mutex::new(None));
        let appender = RecordingDraftAppender {
            message: Arc::clone(&appended),
        };
        let save_response = super::native_save_message_with_appender(
            &state,
            "SaveMessage",
            &payload,
            &session,
            &appender,
        )
        .await;
        let save_body = read_json(save_response).await;
        assert!(save_body["Result"]["error"]
            .as_str()
            .unwrap()
            .contains("Client-provided OpenPGP MIME"));
        assert!(appended.lock().unwrap().is_none());
        assert!(scope.path(&token).unwrap().exists());

        tokio::fs::remove_dir_all(&temp_root).await.unwrap();
    }

    #[tokio::test]
    async fn send_and_save_actions_serialize_embedded_data_images_as_related_parts() {
        let key = [63_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let temp_root = std::env::temp_dir().join(format!(
            "frickmail-data-image-actions-{}",
            super::legacy_random_compose_attachment_token()
        ));
        let mut config = test_config(None);
        config.tmp_dir = temp_root.to_string_lossy().to_string();
        let (state, session) =
            message_body_test_state_with_config(7_942, 7_943, &key, config).await;
        sqlx::query(
            "UPDATE frickmail_mail_accounts
             SET smtp_host = ?, smtp_port = ?, smtp_secure = ?
             WHERE id = ?",
        )
        .bind("8.8.8.8")
        .bind(25_i64)
        .bind("none")
        .bind(7_943_i64)
        .execute(state.db_pool().unwrap())
        .await
        .unwrap();
        let html = "<p>Logo <img src=\"https://example.com/placeholder\" data-x-src=\"data:image/gif;base64,R0lG\"></p>";

        let sent = Arc::new(Mutex::new(None));
        let sender = RecordingSmtpSender {
            succeed: true,
            message: Arc::clone(&sent),
        };
        let response = super::native_send_message_inner_with_sender(
            &state,
            "SendMessage",
            &json!({
                "account_id": 7_943,
                "from": "work@example.com",
                "to": "recipient@example.net",
                "html": html,
                "plain": "Logo"
            }),
            &session,
            Arc::new(std::sync::atomic::AtomicU8::new(super::SEND_PHASE_PRE_SMTP)),
            &sender,
        )
        .await;
        assert_eq!(read_json(response).await["Result"], true);
        let sent_wire = String::from_utf8(sent.lock().unwrap().clone().unwrap()).unwrap();
        assert!(sent_wire.contains("multipart/related"));
        assert!(sent_wire.contains("Content-Type: image/gif; name=\"image.gif\""));
        assert!(sent_wire.contains("Content-ID: <"));
        assert!(sent_wire.contains("R0lG"));
        assert!(!sent_wire.contains("data:image"));

        let saved = Arc::new(Mutex::new(None));
        let appender = RecordingDraftAppender {
            message: Arc::clone(&saved),
        };
        let response = super::native_save_message_with_appender(
            &state,
            "SaveMessage",
            &json!({
                "account_id": 7_943,
                "from": "work@example.com",
                "html": html,
                "plain": "Logo",
                "saveFolder": "Drafts"
            }),
            &session,
            &appender,
        )
        .await;
        assert_eq!(read_json(response).await["Result"]["uid"], 77);
        let saved_wire = String::from_utf8(saved.lock().unwrap().clone().unwrap()).unwrap();
        assert!(saved_wire.contains("multipart/related"));
        assert!(saved_wire.contains("Content-Type: image/gif; name=\"image.gif\""));
        assert!(saved_wire.contains("R0lG"));
        assert!(!saved_wire.contains("data:image"));
        assert!(!temp_root.join("compose-attachments").exists());
    }

    #[tokio::test]
    async fn upload_attachments_caches_fetched_mime_parts() {
        let key = [54_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let temp_root = std::env::temp_dir().join(format!(
            "frickmail-upload-cache-{}",
            super::legacy_random_compose_attachment_token()
        ));
        let mut config = test_config(None);
        config.tmp_dir = temp_root.to_string_lossy().to_string();
        let (state, session) = message_body_test_state_with_config(1942, 1943, &key, config).await;

        let raw_key_json = json!({
            "folder": "INBOX",
            "uid": 57,
            "mimeIndex": "2",
            "fileName": "test.pdf",
            "mimeType": "application/pdf",
        });
        let raw_key = URL_SAFE_NO_PAD.encode(raw_key_json.to_string());

        let fetch_calls = Arc::new(AtomicUsize::new(0));
        let response = super::native_legacy_message_upload_attachments_with_fetcher(
            &state,
            "MessageUploadAttachments",
            &json!({
                "account_id": 1943,
                "attachments": [raw_key.clone()],
            }),
            &session,
            Duration::from_secs(5),
            {
                let fetch_calls = Arc::clone(&fetch_calls);
                move |_config, _password, _folder, uid, _mime_index| {
                    let fetch_calls = Arc::clone(&fetch_calls);
                    async move {
                        // Verify uid is passed through
                        assert_eq!(uid, 57);
                        fetch_calls.fetch_add(1, Ordering::SeqCst);
                        Ok(Some(b"UPLOAD-CONTENT".to_vec()))
                    }
                }
            },
        )
        .await;

        let body = read_json(response).await;
        assert_eq!(body["Action"], "MessageUploadAttachments");
        let results = body["Result"].as_array().unwrap();
        assert_eq!(results.len(), 1);
        let entry = &results[0];
        assert!(entry["tempName"].is_string());
        assert_eq!(entry["mimeType"], "application/pdf");
        assert_ne!(entry["tempName"].as_str().unwrap(), "");
        assert_eq!(fetch_calls.load(Ordering::SeqCst), 1);

        let cached_response = super::native_legacy_message_upload_attachments_with_fetcher(
            &state,
            "MessageUploadAttachments",
            &json!({
                "account_id": 1943,
                "attachments": [raw_key],
            }),
            &session,
            Duration::from_secs(5),
            |_config, _password, _folder, _uid, _mime_index| async move {
                panic!("cache hit must not refetch the MIME part")
            },
        )
        .await;
        let cached = read_json(cached_response).await;
        assert_eq!(cached["Result"][0]["tempName"], entry["tempName"]);

        tokio::fs::remove_dir_all(&temp_root).await.unwrap();
    }

    #[tokio::test]
    async fn upload_attachments_map_parallel_fetch_results_in_input_order() {
        let key = [55_u8; fm_user::CREDENTIAL_KEY_BYTES];
        let temp_root = std::env::temp_dir().join(format!(
            "frickmail-upload-sequential-{}",
            super::legacy_random_compose_attachment_token()
        ));
        let mut config = test_config(None);
        config.tmp_dir = temp_root.to_string_lossy().to_string();
        let (state, session) = message_body_test_state_with_config(2942, 2943, &key, config).await;
        let raw_keys = [57_u32, 58]
            .into_iter()
            .map(|uid| {
                URL_SAFE_NO_PAD.encode(
                    json!({
                        "folder": "INBOX",
                        "uid": uid,
                        "mimeIndex": "2",
                        "fileName": format!("part-{uid}.bin"),
                        "mimeType": "application/octet-stream",
                    })
                    .to_string(),
                )
            })
            .collect::<Vec<_>>();
        let calls = Arc::new(Mutex::new(Vec::new()));

        let response = tokio::time::timeout(
            Duration::from_millis(500),
            super::native_legacy_message_upload_attachments_with_fetcher(
                &state,
                "MessageUploadAttachments",
                &json!({
                    "account_id": 2943,
                    "attachments": raw_keys,
                }),
                &session,
                Duration::from_millis(100),
                {
                    let calls = Arc::clone(&calls);
                    move |_config, _password, _folder, uid, _mime_index| {
                        let calls = Arc::clone(&calls);
                        async move {
                            calls.lock().unwrap().push(uid);
                            let delay = if uid == 57 { 60 } else { 5 };
                            tokio::time::sleep(Duration::from_millis(delay)).await;
                            Ok(Some(format!("part-{uid}").into_bytes()))
                        }
                    }
                },
            ),
        )
        .await
        .expect("parallel attachment fetches must complete within the deadline");
        let body = read_json(response).await;

        let calls = calls.lock().unwrap().clone();
        assert_eq!(
            calls.len(),
            2,
            "every attachment must be fetched exactly once"
        );
        assert!(body["Result"]
            .as_array()
            .unwrap()
            .iter()
            .all(Value::is_object));
        let result_temp_names = body["Result"]
            .as_array()
            .unwrap()
            .iter()
            .map(|entry| entry["tempName"].as_str().unwrap().to_owned())
            .collect::<Vec<_>>();
        let expected_temp_names = [(57, &raw_keys[0]), (58, &raw_keys[1])]
            .into_iter()
            .map(|(uid, raw_key)| {
                assert!(calls.contains(&uid));
                hex::encode(Sha1::digest(raw_key.as_bytes()))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            result_temp_names, expected_temp_names,
            "completed attachment results must retain their original payload indexes"
        );
        tokio::fs::remove_dir_all(&temp_root).await.unwrap();
    }

